      "conceptExplanation": "관세법 제2조의 용어 정의는 1과목(수출입통관절차)에서 거의 매년 출제되는 최빈출·최기본 유형으로, 통관 전 과정의 출발점이 되는 7대 핵심 개념을 정확히 구분하는 것이 핵심이다.\n\n[1] 내국물품(제2조 제5호) — ① 우리나라에 있는 물품으로서 외국물품이 아닌 것, ② 우리나라의 선박 등이 공해(公海)에서 채집·포획한 수산물 등, ③ 입항전수입신고(제244조)가 수리된 물품, ④ 수입신고수리 전 반출승인(제252조)을 받아 반출된 물품, ⑤ 수입신고전 즉시반출신고(제253조)를 하고 반출된 물품. 즉 '수입신고가 수리(또는 수리 의제)되는 순간' 외국물품이 내국물품으로 전환된다.\n\n[2] 외국물품(제2조 제4호) — ① 외국으로부터 우리나라에 도착한 물품(외국 선박이 공해에서 채집·포획한 수산물 포함)으로서 수입신고가 수리되기 전의 것, ② 수출의 신고가 수리된 물품. 핵심은 '수출신고가 수리되면 아직 국내에 있어도(선적 전이라도) 외국물품'이라는 점이다.\n\n[3] 수입(제2조 제1호) — 외국물품을 우리나라에 반입(보세구역을 경유하는 것은 보세구역으로부터 반입)하거나 우리나라에서 소비·사용하는 것. 단, 국제무역선·국제무역기 등 외국을 항행하는 운송수단 안에서의 소비·사용, 선(기)용품의 소비·사용 등은 수입에서 제외한다(제239조 등의 예외).\n\n[4] 수출(제2조 제2호) — 내국물품을 외국으로 반출하는 것.\n\n[5] 반송(제2조 제3호) — 국내에 도착한 외국물품이 수입통관절차를 '거치지 아니하고' 다시 외국으로 반출되는 것. '수입통관절차를 거친 뒤 반출'은 반송이 아니다.\n\n[6] 통관(제2조 제13호) — 관세법에 따른 절차를 이행하여 물품을 '수출·수입 또는 반송'하는 것. 환적은 통관에 포함되지 않는다.\n\n[7] 환적/복합환적(제2조) — 환적은 '동일한 세관 관할구역' 안에서 입국·입항 운송수단의 물품을 출국·출항 운송수단으로 옮겨 싣는 것. 복합환적은 입국·입항 운송수단의 물품을 '다른 세관 관할구역으로 운송하여' 출국·출항 운송수단으로 옮겨 싣는 것. 운송수단 사이를 옮겨 싣는 행위라는 점에서 보세구역 반입을 전제로 하는 반송과 구별된다.\n\n이 유형은 ① 부정형('틀린 것')과 긍정형('맞는 것') 발문이 번갈아 나오고, ② 물품의 법적 성질이 어느 시점에 내국물품↔외국물품으로 전환되는지, ③ 반송·환적·수출의 행위 개념을 서로 바꿔치기하는 방식으로 자주 함정을 만든다.",
      "trapAnalysis": "이 유형의 대표적 함정 패턴은 다음과 같다.\n\n(1) 행위 개념 바꿔치기 — '반송'의 정의에 '수입통관절차를 거쳐'라는 문구를 끼워 넣는 함정(대표문항 ②). 반송은 반드시 '수입통관절차를 거치지 아니하고' 다시 외국으로 반출되는 것이므로, '통관절차를 거친 뒤 반출'로 서술하면 무조건 오답이다.\n\n(2) 물품 성질 전환시점 함정 — '입항전수입신고가 수리된 물품은 외국물품이다'(2019 Q2, 2020 Q21), '수입신고수리전 반출승인을 받아 반출된 물품은 외국물품이다'(2022 Q21), '공해에서 우리 선박이 잡은 수산물로 수입신고 수리된 것은 외국물품이다'처럼 '내국물품'을 '외국물품'으로 뒤집는 패턴. 반대로 '수출신고가 수리된 물품은 (적재 전이라) 내국물품이다'(2020 Q21)처럼 외국물품을 내국물품으로 뒤집기도 한다.\n\n(3) 통관의 범위 함정 — '통관에 환적이 포함된다'거나(2022 Q21 ③, 2025 Q1 ③) '통관에 반송이 포함되지 않는다'(2020 Q21 ⑤)는 식으로 통관의 구성요소(수출·수입·반송)를 늘리거나 빼는 패턴.\n\n(4) 수입의 예외 누락/추가 — '여행자가 휴대품을 국제무역기에서 소비하는 경우를 수입에 포함한다'(2023 Q1)처럼 국제무역선·기 내 소비라는 '수입 제외' 예외를 무시하는 함정.\n\n(5) 환적 vs 복합환적 vs 반송 혼동 — 환적('동일 세관 관할구역')과 복합환적('다른 세관 관할구역으로 운송')의 관할구역 표현을 맞바꾸거나, 운송수단 간 이적(=환적)을 반송물품 범위로 포함시키는 함정(2019 Q18 ①).",
      "answerKey": "정답은 ②(반송)이다. 관세법 제2조 제3호상 '반송'이란 국내에 도착한 외국물품이 '수입통관절차를 거치지 아니하고' 다시 외국으로 반출되는 것을 말한다. 그러나 ②는 '수입통관절차를 거쳐 보세구역에서 반출된 상태에서' 재반출한다고 하여 반송의 핵심요건(통관 미경유)을 정반대로 서술하였으므로 틀린 설명이다.\n\n나머지는 모두 옳다. ① 수출=내국물품을 외국으로 반출(제2조 제2호)로 정확하다. ③ 수입의 정의(외국물품을 우리나라에 반입하거나 국내에서 소비·사용)로 보세구역 경유 시 괄호 설명까지 조문 그대로다(제2조 제1호). ④ 환적='동일한 세관 관할구역' 안에서 입항 운송수단→출항 운송수단으로 옮겨 싣는 것으로 정확하다. ⑤ 통관=관세법 절차를 이행하여 물품을 수출·수입 또는 반송하는 것(제2조 제13호)으로 환적이 빠진 정확한 정의다.",
