      "lawBasis": "관세법 제19조(납세의무자) — 제1항제1호: 원칙적 납세의무자(화주), 화주 불분명 시 위탁자·물품수신인·양수인 / 제1항 각 호(특히 제10호 가·나·다목): 도난·분실물품(보세구역 장치=운영인·화물관리인, 보세운송=신고·승인을 받은 자, 기타=보관인·취급한 자) / 우편물=수취인 / 경합 시 특별납세의무자 우선(현행 제19조제5항, 구 제6항) / 공유물·공동사업 물품의 수입화주와의 연대납부 의무(현행 제19조제5항, ※제20조 아님 — 제20조는 「납부책임의 승계」 조문). 관세법 제41조(양도담보재산에서의 관세 징수) — 다른 수단으로 징수할 수 없는 경우에 한해 조건부 징수('우선적' 징수 아님).",
