      "conceptExplanation": "관세는 「과세물건(과세대상이 되는 물품의 성질·수량)」이 어느 시점에 확정되는가에 따라 적용 세율·과세가격이 달라지므로, 「과세물건 확정시기(관세법 제16조)」와 「적용 법령의 시기(제17조)」는 1과목 최빈출 출제 영역이다.\n\n[1] 원칙. 관세는 「수입신고(입항전수입신고 포함)를 하는 때」의 물품의 성질과 수량에 따라 부과한다(제16조 본문). 적용 법령도 원칙적으로 「수입신고 당시」의 법령을 적용한다(제17조 본문). 즉 정상적인 수입통관은 '수입신고 시점'이 기준이다.\n\n[2] 예외 11가지 — 과세물건 확정시기(제16조 각 호). 비정상적 통관·무신고 사용 등의 경우 신고 시점이 없으므로 별도 시점을 정해 둔다. 시험에 반복 출제되는 핵심 예외는 다음과 같다.\n - 수입신고 전 즉시반출신고를 하고 반출한 물품(제253조): 「즉시반출신고를 한 때」. (※'수입신고를 한 때'가 아님 — 2022 Q6 함정)\n - 보세건설장에 반입된 외국물품으로 건설공사 완료 전 가동된 경우: 「사용 전 수입신고를 한 때」.\n - 보세운송 외국물품이 지정기간 내에 목적지에 도착하지 아니하여 관세를 징수하는 물품: 「보세운송을 신고하거나 승인받은 때」. (※'지정기간이 만료된 때'가 아님 — 2020 Q19 함정)\n - 수입신고가 수리되기 전에 소비·사용하는 물품(제239조 비대상 제외): 「소비하거나 사용한 때」.\n - 도난물품 또는 분실물품: 「도난되거나 분실된 때」.\n - 관세법에 따라 매각되는 물품: 「매각된 때」.\n - 우편으로 수입되는 물품(정식 수입신고 대상 우편물은 제외): 「통관우체국에 도착한 때」.\n - 그 밖에 수입신고를 하지 아니하고 수입된 물품: 「수입된 때」.\n\n[3] 적용 법령의 시기(제17조). 원칙은 수입신고 당시 법령이며, 제16조 각 호의 예외에 해당하는 물품(즉시반출·보세건설장·보세운송 미도착·도난분실·매각·소비사용·우편 등)은 「그 사실이 발생한 날(각 호에서 정한 확정시기)」에 시행되는 법령을 적용한다. 특히 보세건설장 반입 외국물품의 적용 법령은 「사용 전 수입신고가 수리된 날」의 법령이라는 점이 반복 출제된다(2019 Q4·2021 Q2). '반입된 날' '사용전 수입신고 당시'로 바꾸면 오답이다.\n\n[4] 과세표준(제15조)과의 결합 출제. 관세의 과세표준은 「수입물품의 가격 또는 수량」이며(제15조), 관세는 「수입신고하는 때의 물품의 성질과 수량」에 따라 부과한다(제16조). 빈칸형으로 '가격-수량-성질-수량'을 묻는 형태로도 출제된다(2020 Q23). 즉 과세표준=가격 또는 수량, 부과기준=성질과 수량으로 단어가 다르다는 점에 주의한다.",
      "trapAnalysis": "이 유형의 함정은 「확정시기를 한 칸씩 미루거나 비슷한 사건으로 바꿔치기」하는 패턴이 핵심이다.\n① 보세운송 미도착: 정답 시점은 '보세운송을 신고하거나 승인받은 때'인데, 출제자는 자주 '보세운송 지정기간이 만료된 때'(2020 Q19 ③) 또는 '목적지에 도착하지 아니한 때'로 바꿔 오답을 만든다. 사고의 흐름상 '기간 만료'가 그럴듯해 보여 가장 많이 낚인다.\n② 즉시반출: 정답 시점은 '즉시반출신고를 한 때'인데, '수입신고를 한 때'(2022 Q6 ④)로 바꾼다. 즉시반출은 신고 후 10일 내 수입신고를 별도로 하므로 두 시점이 다르다는 점을 노린다.\n③ 보세건설장(적용 법령): 정답은 '사용 전 수입신고가 수리된 날'의 법령인데, '보세건설장에 반입된 날'(2021 Q2 ②)이나 '사용전 수입신고 당시'(2019 Q4 ③)로 미세하게 비틀어 오답을 만든다.\n④ 과세표준 빈칸형: '성질'을 '가격'이나 '규격'으로 바꾸거나(2020 Q23), 과세표준을 '수량·중량'으로 바꿔 제15조와 제16조의 용어를 섞는다.\n⑤ 사례형(2023 Q3): '보세구역 반입된 때'를 부과 기준으로 제시해 '수입신고 당시'(제16조) 원칙을 어기게 유도한다.",
      "answerKey": "발문이 '틀린 것'을 고르는 부정형이다. 정답은 ③이다. 관세법 제16조는 보세운송 외국물품이 지정기간 내에 목적지에 도착하지 아니하여 관세를 징수하는 경우 과세물건 확정시기를 「보세운송을 신고하거나 승인받은 때」로 규정한다. ③은 이를 '보세운송 지정기간이 만료된 때'라 하여 규정과 다르므로 틀린 설명이다.\n나머지는 모두 옳다. ① 수리 전 소비·사용 물품은 '소비·사용한 때'(제16조), ② 도난·분실물품은 '도난·분실된 때', ④ 우편물(정식 수입신고 대상 제외)은 '통관우체국에 도착한 때', ⑤ 수입신고 전 즉시반출 물품은 '즉시반출신고를 한 때'로 모두 제16조 각 호에 부합한다.",
