      "conceptExplanation": "신고납부제(관세법 제38조)에서 일단 확정된 세액을 사후에 바로잡는 5가지 제도를 구분하는 것이 이 유형의 핵심이다. 「언제(시점)·누가(주체)·무엇을(부족/과다)·기한·이자」 5개 축으로 정리한다.\n\n① 정정(제38조 제4항): '납부 전' 단계. 납세의무자가 납세신고한 세액에 과부족(많든 적든)이 있음을 알게 된 때 스스로 고치는 것. 아직 납부 전이므로 가산세·이자 없음. 납부기한은 '당초(종전) 납부기한'이 그대로 유지된다(정정일로 바뀌지 않음). 납부서 재발행 시 납부서번호·납부기한은 변경하지 않는다.\n\n② 보정(제38조의2): '납부 후, 세액이 부족'한 경우의 자진 보완. 신고납부한 날부터 '6개월(보정기간)' 이내에 세관장에게 보정신청. 납부기한은 '보정신청을 한 날의 다음 날'까지. 가산세는 없으나, 납부기한(수리전납부는 납부일) 다음 날부터 보정신청일까지 기간에 시행령 제56조 제2항의 이율을 적용한 '보정이자'를 가산한다(단, 신청인이 과실 없이 부족하게 신고한 경우 등은 면제될 수 있음).\n\n③ 수정신고(제38조의3 제1항): '납부 후, 세액 부족'을 보정기간(6개월)이 '지난 후' 알게 된 경우. 제척기간(5년) 내에 수정신고할 수 있으며, '수정신고한 날의 다음 날'까지 납부한다. 부족세액에는 가산세가 부과된다.\n\n④ 경정(제38조의3 제6항): 세관장이 직권으로 부족·과다 세액을 바로잡는 처분.\n\n⑤ 경정청구(제38조의3 제2항~): '세액이 과다(과다납부)'한 경우 납세의무자가 환급을 받기 위해 세관장에게 청구. 최초로 납세신고한 날부터 '5년' 이내. 세관장은 청구를 받은 날부터 '2개월' 이내에 경정하거나 경정할 이유가 없다는 뜻을 통지해야 하고, 청구인이 2개월 내 통지를 받지 못하면 그 2개월이 되는 날의 다음 날부터 불복(이의신청·심사·심판청구)을 제기할 수 있다. 특례: 소송 판결로 과다납부를 안 날부터 2개월 이내(후발적 사유), 과세가격 조정 경정(제38조의4)은 처분 통지받은 날부터 3개월 또는 최초 신고일부터 5년 이내.\n\n핵심 가르기: '부족=보정/수정/직권경정', '과다=정정(납부전)/경정청구(납부후 환급)'. 기간은 '보정 6개월 / 경정청구·수정·제척기간 5년 / 세관장 처리 2개월'로 묶어 외운다.",
      "trapAnalysis": "이 유형의 함정은 5개 제도의 요소를 서로 바꿔치기하는 것이다.\n\n1) '부족↔과다' 바꿔치기: 보정·수정·직권경정은 '부족'한 경우인데 '과다'로 바꾸면 오답(②④). 반대로 경정청구는 '과다'한 경우인데 '부족'으로 적으면 오답. 2022 Q16 가번(=①)이 \"과다한 것을 안 때 세액보정을 하여야 한다\"고 하여 보정과 경정청구(과다)를 뒤섞은 대표적 함정이다.\n\n2) '기간 숫자' 바꿔치기: 보정 6개월을 3개월로(①), 경정청구·수정·제척기간 5년을 3년으로(2024 Q16 ①②, 2021 Q4 라·마=④⑤), 세관장 처리 2개월을 1개월/3개월로(2024 Q16 ③④에서 1개월, 2023 Q4 다번 \"3개월 이내 경정\") 바꾸는 패턴. (주의: '1개월' 변형은 2024 Q16에만 등장하며 2021 Q4 선지는 5년·3개월·6개월 조합을 쓴다.)\n\n3) '납부기한' 함정: 정정의 납부기한은 '당초 납부기한'인데 '정정일'로(2019 Q11 가번, 정답), 보정의 납부기한은 '보정신청일의 다음 날'인데 '보정신청일 당일' 또는 '보정한 날로부터 15일'로(2022 Q16 라번=④) 바꾸는 패턴. 2023 Q2 다번은 정정 납부기한을 '당초 납부기한의 다음 날'로 비틀어 오답.\n\n4) '이자/가산세' 함정: 정정은 무이자인데 가산금이 있다고 하거나(2019 Q11 라번은 무이자가 맞아 정답 아님), 보정의 '보정이자'(시행령 제56조 제2항 이율) 가산을 빠뜨리는 패턴.\n\n5) '제도 혼동' 함정: 제척기간(부과)은 중단·정지가 없는데 '통고처분 등으로 중단된다'고 하여 소멸시효(징수권) 규정과 섞는 패턴(2023 Q4 가번).",
      "answerKey": "정답은 ③(A=부족, B=6개월, C=다음 날)이다.\n- A=부족: 세액 보정은 '신고납부한 세액이 부족'하거나 과세가격·품목분류 등에 오류가 있는 경우의 자진 보완 제도다. '과다'한 경우는 경정청구(환급) 대상이므로 ②④는 오답.\n- B=6개월: 보정신청 기간은 '신고납부한 날부터 6개월(보정기간)'이다. 3개월로 적은 ①은 오답.\n- C=다음 날: 보정신청 시 납부기한은 '보정신청을 한 날의 다음 날'까지다. '다음 다음 날'로 적은 ⑤는 오답.\n세 요소가 모두 부합하는 ③만이 정답이다.",
