      "question": "관세법 제226조에 따른 세관장확인물품 및 확인방법 지정 고시에서 사용하는 용어의 뜻이다. ( ) 안에 들어갈 내용으로 바르게 나열한 것은?\n\n· ( A )(이)란 수출입시 허가·승인 등의 증명이 필요한 물품을 수출입하려는 자가 요건확인기관의 장에게 허가·승인 그 밖의 조건을 구비하기 위하여 신청하는 것을 말한다.\n· ( B )(이)란 관련 법령에 따라 수출입 요건이 면제되는 물품으로 면제절차는 이 고시 또는 관련 법령을 적용한다.\n· ( C )(이)란 수출입신고시 세관장확인을 생략하고 통관이후 요건확인기관이 사후적으로 관리하도록 관세청장과 요건확인기관의 장이 협의하여 지정한 기업을 말한다.\n\n보기: (A), (B), (C)",
