      "lawBasis": "관세법 제21조(관세부과의 제척기간) 제1항(원칙 5년, 부정포탈 10년)·제2항(불복·판결 등 특례 1년); 관세법 시행령 제6조(관세부과 제척기간의 기산일); 관세법 제22조(관세징수권 등의 소멸시효)·시행령 제7조(소멸시효의 중단·정지) — 제척기간과의 구별 비교",
