      "lawBasis": "관세법 제237조(통관의 보류) 제1항 각 호 — 제1호 제241조·제244조에 따른 신고서 기재사항 보완 필요, 제2호 제245조에 따른 제출서류 미비 보완 필요, 제3호 이 법에 따른 의무사항 위반 또는 국민보건 등 위해 우려, 제4호 제246조의3제1항에 따른 안전성 검사 필요, 제4의2호 안전성 검사 결과 불법·불량·유해 물품으로 확인된 경우, 제5호 「국세징수법」 제30조 및 「지방세징수법」 제39조의2에 따라 세관장에게 강제징수·체납처분이 위탁된 해당 체납자가 수입하는 경우, 제6호 그 밖에 이 법에 따라 필요한 사항을 확인할 필요가 있다고 인정하여 대통령령으로 정하는 경우(구법상 '관세청장이 정하는 경우'). ※'관세범칙 고발·조사'는 제237조 제1항에 독립된 호로 명시되지 않으며, 제3호(의무위반)·제6호(확인 필요 대통령령 위임)에 포섭되는 운용상 보류사유로 본다. 관련 조문: 관세법 제246조의3(물품에 대한 안전성 검사), 제235조(지식재산권 보호·병행수입), 국세징수법 제30조(강제징수의 위탁).",
