      "lawBasis": "관세법 제238조(보세구역 반입명령), 같은 법 시행령 제245조(반입명령): 제1항(명령 주체 관세청장·세관장, 대상 사유, 단서=신고수리 후 3개월 경과 또는 관계 행정기관의 장의 시정조치 시 명령 불가)·제2항(반입명령서 송달, 주소·거소 불명 시 공시송달)·제3항(반입기한, 승인 시 연장 가능)·제4항·제5항(보완·정정 후 반출·반송·폐기, 수출신고수리 반출 전 물품 폐기 시 당초 수출신고 수리 취소 간주)·제6항(운송료·보관료 등 비용은 반입의무자 부담). 표시 위반은 관세법 제230조·제230조의2·제235조와 연계. ※ 비용 부담 근거를 '시행규칙'이 아닌 '시행령 제245조제6항'으로 정정.",
