      "conceptExplanation": "수입신고의 시기는 물품이 우리나라에 들어오는 단계에 따라 4가지로 구분되며, 수입하려는 자는 이 중에서 필요에 따라 「요건에 맞는 신고방법을 선택」하여 신고할 수 있다(임의 선택제). ① 출항전신고: 물품을 적재한 선박·항공기가 적재항(외국)을 출항하기 전에 하는 신고. ② 입항전신고: 출항 후 우리나라에 입항하기 전에 하는 신고. ③ 보세구역 도착전신고: 입항 후 물품이 반입될 보세구역에 도착하기 전에 하는 신고. ④ 보세구역 장치후신고: 물품을 보세구역에 반입(장치)한 후에 하는 신고. \n\n[신고세관] 출항전신고·입항전신고는 「입항예정지를 관할하는 세관장」에게, 보세구역 도착전신고는 「물품이 도착할(반입될) 보세구역을 관할하는 세관장」에게, 보세구역 장치후신고는 「물품이 장치된 보세구역을 관할하는 세관장」에게 한다. 즉 도착전신고는 '도착할' 보세구역 기준이며 '출발한' 보세구역이 아니다(빈출 함정).\n\n[출항전·입항전신고의 시기 제한] 출항전신고와 입항전신고는 해당 물품을 적재한 선박 등이 우리나라에 「입항하기 5일 전(항공기는 1일 전)」부터 할 수 있다(관세법 시행령 제249조 제1항). 따라서 \"입항 전에는 언제든지 할 수 있다\"는 표현은 틀린 것이다.\n\n[입항전신고의 제한·특칙] (가) 세율이 인상되거나 새로운 수입요건을 갖추도록 요구하는 법령이 적용되거나 적용될 예정인 물품 등은 해당 물품을 적재한 선박 등이 우리나라에 「도착된 후」에 수입신고하여야 한다(법 제244조 제2항). (나) 농·수·축산물이나 그 가공품으로서 수입신고하는 때와 입항하는 때의 「관세율표 번호(HS) 10단위 또는 과세단위(수량·중량)가 변경되는 물품」은 입항 전에 신고할 수 없다(시행령 제249조 제3항). (다) 입항전수입신고가 된 물품은 우리나라에 「도착한 것」으로 본다. (라) 입항전신고한 물품이 검사대상으로 결정되지 아니한 경우에는 입항 전에 수입신고를 수리할 수 있으나(다만 세율 변경 물품 등은 입항 전 수리 불가), 검사대상으로 결정된 물품은 검사 후(보세구역 반입 후) 수리한다 — 신고를 취하하고 다시 신고하는 것이 아니다.\n\n[수입신고 효력발생시점·명의] 수입신고의 효력발생시점은 전송된 신고자료가 통관시스템에 접수된 시점이며, 수입신고는 관세사·관세법인·통관취급법인 등이나 수입화주의 명의로 한다.",
      "trapAnalysis": "이 유형의 오답 함정은 크게 네 가지다. ① 신고세관 뒤바꾸기: 보세구역 도착전신고를 '도착할' 보세구역이 아니라 '출발한 보세구역'을 관할하는 세관장에게 한다고 서술(2023 Q14 ④ — 대표문항의 정답 함정). 도착전신고는 아직 도착하지 않은 단계이므로 출발지 개념 자체가 성립하지 않는다. ② 입항전신고 시기 과장: \"입항하기 전에는 언제든지 할 수 있다\"고 하여 '입항 5일 전(항공기 1일 전)' 제한을 누락(2021 Q14는 '맞는 것은?' 긍정형 문항이며, 정답은 세율 인상 예정 물품 도착 후 신고를 다룬 ③. '언제든지' 과장은 오답 선지 ①에 등장). ③ 세율/과세단위 변경 물품의 방향 뒤집기(이 유형의 핵심·최빈 함정): '관세율표 10단위가 변경되는 농수축산물 가공품은 입항전신고 불가'는 맞는 설명이지만, '과세단위(수량·중량)가 변경되는 물품은 입항 전에 신고할 수 있다'처럼 규정을 정반대로 서술(2024 Q11 ⑤ 및 2025 Q6 ④ — 둘 다 정답 함정이며, HS 10단위·과세단위 변경 물품은 모두 입항전신고 불가, 시행령 제249조③). 또 '세율이 인상되는 물품은 도착 후 신고'는 맞는 설명으로 출제(2021 Q14 ③, 법 제244조②). ④ 입항 전 수리 조건 누락: 일반물품은 '검사대상 아님' 조건만으로 입항 전 수리가 가능하나, 농수축산물 등 세율변경 물품은 '검사대상 아님'에 더해 '입항 시 세율 불변경' 조건까지 충족해야 입항 전 수리가 가능하다(시행령 제249조 관련). 검사대상 선정 시 신고를 '취하 후 재신고'한다는 서술도 오답(2021 Q14 ④).",
      "answerKey": "정답은 ④. 보세구역 도착전신고는 해당 물품이 「도착할(반입될) 보세구역」을 관할하는 세관장에게 하여야 하는데, ④는 「출발한 보세구역」을 관할하는 세관장에게 한다고 하여 신고세관을 정반대로 서술했으므로 틀린 설명이다. 나머지는 모두 옳다. ①은 4가지 신고시기 중 요건에 맞는 방법을 임의 선택할 수 있다는 선택제 규정으로 옳다. ②는 출항전·입항전신고를 '입항예정지 관할 세관장'에게 한다는 신고세관 규정으로 옳다. ③은 출항전·입항전신고를 선박 입항 5일 전(항공기 1일 전)부터 할 수 있다는 시기 규정으로 옳다. ⑤는 장치후신고를 '물품이 장치된 보세구역 관할 세관장'에게 한다는 신고세관 규정으로 옳다.",
