      "question": "관세법령상 ( ) 안에 들어갈 내용이 순서대로 맞는 것은?\n수출신고가 수리된 물품은 수출신고가 수리된 날부터 ( )일 이내에 운송수단에 적재하여야 한다. 다만, 기획재정부령으로 정하는 바에 따라 1년의 범위에서 적재기간의 연장승인을 받은 것은 그러하지 아니하다. 세관장은 위에서 정한 기간 내에 적재되지 아니한 물품에 대하여는 대통령령으로 정하는 바에 따라 수출신고의 수리를 ( )할 수 있다.",
