      "conceptExplanation": "관세법 제251조(수출신고수리물품의 적재 등)에 관한 유형이다. 핵심 골격은 「기간 + 연장 + 미이행 시 제재」 3요소로, 매년 빈칸채우기 또는 옳은/틀린 것 고르기로 변형 출제된다.\n\n[1] 적재기간(원칙): 수출신고가 수리된 물품은 수출신고가 수리된 날부터 '30일' 이내에 운송수단(우리나라와 외국 간을 왕래하는 운송수단)에 적재하여야 한다. 기산점은 '수출신고일'이 아니라 '수출신고가 수리된 날'이다.\n\n[2] 적재기간 연장: 기획재정부령으로 정하는 바에 따라 '1년'의 범위에서 적재기간의 연장'승인'을 받은 것은 30일 원칙의 예외이다. 연장 절차의 법적 성질은 '허가'가 아니라 '승인'이며, 연장 한도는 '6개월'이나 '2년'이 아닌 '1년'이다.\n\n[3] 미적재 시 제재: 세관장은 위 기간(30일 또는 연장기간) 내에 적재되지 아니한 물품에 대하여는 대통령령으로 정하는 바에 따라 수출신고의 수리를 '취소'할 수 있다. 신고인 요청에 의한 '취하'나 세관장의 직권 '각하'가 아니라 세관장의 직권 '취소'라는 점이 함정 포인트이다.\n\n[4] 적재 이행관리(고시): 적재지검사 대상물품은 물품검사가 완료된 후 운송수단에 적재하여야 한다. 통관지 세관장은 적재기간이 경과한 수출신고수리물품에 대하여 적재 확인이 되지 않으면 수출신고수리를 취소한다는 '예정통보'를 하여야 하고, 예정통보를 받은 신고인은 통보일부터 '14일' 이내에 적재 화물 유무를 원인규명하고 이미 적재된 물품이 있으면 정정 등 조치를 하여야 한다.",
      "trapAnalysis": "이 유형의 함정은 세 가지 변수의 '숫자·용어 바꿔치기'에 집중된다.\n\n(1) 적재기간 숫자 함정: 정답 '30일'을 '60일'로 바꿔 제시한다(2019 Q21의 ④⑤). 또한 기산점을 '수출신고일'로 슬쩍 바꾸는 변형도 있다(정답은 '수출신고가 수리된 날').\n\n(2) 연장기간 숫자 함정: 가장 빈번한 오답 유도가 연장한도이다. 정답 '1년'을 '6개월'(2023 Q23의 ②) 또는 '2년'(2021 Q25의 ②, 틀린 것 정답)으로 바꾼다. 옳은/틀린 것 유형에서는 '2년의 범위' 선지가 곧 틀린 설명=정답이 된다.\n\n(3) 미적재 제재 용어 함정: '취소'를 '각하'·'취하'로 바꾼다(2019 Q21의 ①②). 취하는 '신고인 요청', 각하는 '신고요건 미비 시 세관장 직권 배척'인 반면, 미적재 제재는 세관장의 '수리 취소'이다. 세 용어의 주체·사유를 헷갈리게 만든다.\n\n(4) 연장의 법적 성질 함정: '승인'을 '허가'로 바꾼다(2025 Q18의 ①③⑤). 적재기간 연장은 '허가'가 아니라 '승인'이다.\n\n(5) 이행관리 절차 함정: 적재기간 경과 후 원인규명 기한 '14일'을 다른 숫자로, 적재지검사 완료 후 적재 의무를 신고지검사로 뒤바꾸는 변형이 있다.",
      "answerKey": "정답은 ③(30 - 취소)이다.\n- ③ 정답: 적재기간 '30일', 미적재 시 수출신고수리 '취소'가 관세법 제251조 제1항·제2항에 정확히 부합한다.\n- ① 오답: 적재기간 30일은 맞으나, 미적재 시 조치는 '각하'가 아니라 '취소'이다(각하는 신고요건 미비 시 세관장의 직권 배척).\n- ② 오답: 30일은 맞으나, 미적재 시 조치는 '취하'가 아니라 '취소'이다(취하는 신고인 요청에 의한 신고 철회).\n- ④ 오답: 미적재 조치는 '취소'로 맞으나, 적재기간이 '60일'이 아니라 '30일'이다.\n- ⑤ 오답: 적재기간(30일)·조치(취소) 모두 틀려, '60일·각하'는 둘 다 어긋난다.",
