      "lawBasis": "관세법 제251조(수출신고수리물품의 적재 등) 제1항·제2항. 제1항: 수출신고가 수리된 물품은 수출신고가 수리된 날부터 30일 이내에 운송수단에 적재하여야 하며, 기획재정부령으로 정하는 바에 따라 1년의 범위에서 적재기간 연장승인을 받을 수 있음. 제2항: 세관장은 기간 내에 적재되지 아니한 물품에 대하여 대통령령으로 정하는 바에 따라 수출신고의 수리를 취소할 수 있음. (※ 일부 연도 자료에서는 동 규정을 제241조로 인용하기도 하나, 현행 관세법상 조문 번호는 제251조이며 내용은 동일하다.) 관련: 신고 취하·각하는 관세법 제250조. 적재 이행관리 세부절차는 수출통관 사무처리에 관한 고시.",
