      "conceptExplanation": "원산지 결정·확인기준은 관세법 제229조(원산지 확인 기준)와 같은 법 시행령 제74조~제76조, 시행규칙 등에 근거하여, 어느 물품이 '어느 나라에서 만들어진 것'인지를 판정하는 규칙이다. 협정관세·반덤핑·원산지표시·통관 등 거의 모든 무역실무의 출발점이 되므로 1과목에서 반복 출제된다.\n\n[1] 완전생산기준(Wholly Obtained): 한 나라에서 그 물품의 전부를 생산·가공·제조한 경우 그 국가를 원산지로 본다. 광산물·식물성생산품·산동물·수산물 등 1차 생산품이 대표적이다. 동물의 경우 출생·사육된 국가가 원산지이고, 광물은 채굴국, 식물은 수확국이 원산지가 된다.\n\n[2] 실질적 변형기준(세번변경기준, CTC): 2개국 이상에 걸쳐 생산·가공·제조된 물품의 원산지는, 그 물품의 생산과정에 사용되는 물품의 품목분류표(HS)상 'HS 6단위(소호, Subheading) 품목번호와 다른 HS 6단위 품목번호'의 물품을 최종적으로 '생산'한 국가로 한다. 즉 투입원료의 HS 6단위가 최종제품의 HS 6단위로 바뀌는(세번이 변경되는) 마지막 실질가공이 일어난 나라가 원산지다. 여기서 단위는 국제 공통 단위인 HS 6단위(소호)이며, 4단위(호)나 8·10단위(국내 세분류 HSK)가 아님에 유의한다.\n\n[3] 단순가공·불인정작업: 보세구역 등에서 포장개선, 재포장, 단순한 절단·선별·구분·세척·혼합·단순조립 등 본질적 특성을 부여하지 않는 가공만 거친 경우에는, 비록 세번(HS 6단위)이 변경되었더라도 그 작업을 한 국가를 원산지로 인정하지 않는다(단순가공 불인정). 또한 단순가공 과정에서 생긴 부스러기·스크랩 등 부산물의 원산지는 그 가공이 실제로 행해진 국가(가공지)로 본다.\n\n[4] 직접운송원칙: 원산지에서 우리나라로 직접 운송된 물품에 한해 해당 원산지를 인정하는 것이 원칙이다. 다만 지리적 또는 운송상의 이유로 단순히 제3국을 경유(환적·일시장치 등 추가가공 없이)한 경우에는 직접운송원칙을 충족한 것으로 본다.\n\n[부수개념] 세관장은 환적·복합환적되는 외국물품 중 원산지를 우리나라로 허위표시하거나 표시를 손상·변경한 물품 등은 유치할 수 있다(관세법 제231조). 또한 세관장에게 제출하는 원산지증명서는 예외적인 경우를 제외하고 제출일부터 소급하여 1년 이내에 발행된 것이어야 한다(시행령 제236조).",
      "trapAnalysis": "trapAnalysis의 핵심 함정 분석(세번변경 단위 4/6/8단위 바꿔치기, 단순가공=세번변경되어도 원산지 불인정, 스크랩=가공지, 동물=사육국, 제3국 단순경유=직접운송 충족)은 모두 관세법·시행규칙 및 근거파일 정답(2019Q17=②, 2022Q2=②, 2023Q18=③)과 정확히 일치하므로 내용상 교정이 필요 없다. 다만 법령 인용 시 '시행령 제74~76조'를 '시행규칙 제74~76조'로 바로잡아야 한다. 이 점만 정정하면 함정 분석은 정확하다.",
      "answerKey": "정답은 ②번이다(2019 Q17, 근거파일 answer:[2]와 일치). 2개국 이상에 걸쳐 생산된 물품의 원산지(실질적 변형=세번변경기준)는 'HS 6단위' 품목번호 변경을 기준으로 최종 생산국을 정하는데, ②는 이를 '4단위'라고 잘못 서술했으므로 틀린 설명(=정답)이다. 나머지 ①(완전생산기준)·③(허위표시 환적물품 유치, 관세법 제231조)·④(보세구역 단순가공은 세번변경되어도 원산지 불인정)·⑤(제3국 단순경유는 직접운송원칙 충족)는 모두 옳은 설명이다. 또한 함께 인용된 2022 Q2의 정답은 [2](사례1 스크랩=한국/가공지, 사례2 소고기=호주/사육국), 2023 Q18의 정답은 [3](6단위)으로 항목 서술과 모두 일치한다.",
