        "원산지표시 보수작업 신청은 '세관장'에게 보수작업승인(신청)서를 제출. 신청·승인·완료확인·통보는 전자통관시스템으로 처리 가능",
        "보세구역에서의 단순 포장개선·선별작업·단순 조립작업으로 세번변경이 생겨도 그 국가를 원산지로 인정하지 않음 (2019 Q17 연계)"
