      "lawBasis": "관세법 제229조(원산지 확인 기준), 제231조(환적물품 등에 대한 유치 등), 제232조(원산지증명서 등) 및 같은 조 제1항 단서, 관세법 시행령 제236조(원산지증명서의 제출 등) — 제2항(원산지증명서 제출면제 5개 대상: ①세관장이 확인할 수 있는 물품 ②우편물(수입신고대상 우편물 제외) ③과세가격이 15만원 이하인 물품 ④개인 무상 송부 탁송품·별송품 ⑤여행자 휴대품)·제4항(원산지증명서는 제출일부터 소급하여 1년 이내에 발행된 것이어야 함), 원산지표시제도 운영에 관한 고시(원산지표시 보수작업 승인·완료확인). ※유효기간(소급 1년) 규정은 현행 시행령 기준 제236조 '제4항'이며, 제출면제 5개 대상은 '제2항'이다(항목 lawBasis의 '제5항'은 제4항으로 정정 필요).",
      "sourceRef": "2019 Q14 · 2022 Q14 · 2020 Q9 · 2020 Q20"
