      "lawBasis": "관세법 제235조(지식재산권 등의 보호) — 제1항(보호대상 열거: 상표권·저작권·저작인접권·품종보호권·지리적표시권등·특허권·디자인권·방위산업기술 ※실용신안권 제외), 제2항(관세청장의 신고 요구), 제3항(세관장의 침해 통보), 제4항(권리자의 담보 제공 후 통관보류·유치 요청), 제5항(세관장의 통관보류·허용 및 유치·해제), 제6항(필요한 사항을 대통령령에 위임), 제7항(세관장의 직권 통관보류·유치 — 침해 '명백' 시). 위임 사항은 관세법 시행령에 규정됨: 통관보류·유치 요청 담보 = 과세가격의 100분의 120, 조세특례제한법상 중소기업 100분의 40, 제소사실 입증 기간 10일, 그리고 「상업적 목적이 아닌 개인용도 소량 여행자휴대품 적용배제」(시행령 제243조). 즉 적용배제는 본법 제235조 제7항이 아니라 시행령 제243조이며, 담보율·기간도 본법이 아닌 시행령에 위임돼 있다. 관련: 관세법 제237조(통관보류), 제238조(보세구역 반입명령).",
