      "conceptExplanation": "관세의 담보는 납세의무자가 관세 등을 확실히 납부하도록 미리 잡아두는 물적·인적 보증으로, 관세법 제24조~제26조가 핵심이다.\n\n(1) 담보의 종류(제24조) — 제공할 수 있는 담보는 ① 금전, ② 국채 또는 지방채, ③ 세관장이 인정하는 유가증권, ④ 납세보증보험증권, ⑤ 토지, ⑥ 보험에 든 등기 또는 등록된 건물·공장재단·광업재단·선박·항공기·건설기계, ⑦ 세관장이 인정하는 보증인의 납세보증서로 한정 열거되어 있다. 즉 부동산은 '토지'와 '보험에 든 등기·등록된 건물 등'만 인정되며, '등록된 차량(자동차)'은 열거 목록에 없다. 납세보증보험증권과 납세보증서는 일정 요건을 갖추어야 한다.\n\n(2) 포괄담보(제24조제4항) — 계속 반복하여 담보를 제공해야 하는 사유가 있으면, 일정 기간 제공할 담보를 한꺼번에(포괄하여) 미리 세관장에게 제공할 수 있다.\n\n(3) 담보의 관세충당(제25조) — 세관장은 담보를 제공한 자가 정해진 기한까지 관세를 납부하지 아니하면 그 담보를 해당 관세에 충당한다. 특히 납세보증보험증권·납세보증서의 경우에는 보증인에게 담보한 관세에 상당하는 금액을 납부할 것을 즉시 통보하는 방법으로 충당한다.\n\n(4) 잔액의 처리 (★빈출 함정) — 세관장은 담보를 관세에 충당하고 남은 금액(잔액)이 있을 때에는 이를 담보를 제공한 자에게 돌려주어야 한다. 다만 돌려줄 수 없는 경우에는 '즉시 국고에 귀속'하는 것이 아니라 '공탁(供託)'하여야 한다는 점이 가장 자주 출제되는 핵심이다.\n\n(5) 담보미제공 시 조치 — 담보를 제공하여야 하는 자가 담보액 확정일부터 10일 이내에 담보를 제공하지 아니하면 세관장은 납부고지를 할 수 있다.\n\n요컨대 이 유형은 ① 담보로 인정되는 '종류 열거'(특히 자동차 제외) 가려내기, ② 충당 절차(보증보험·보증서=보증인에게 즉시 통보), ③ 충당 후 잔액 처리=원칙 반환·예외 공탁(국고귀속 아님) 세 축을 묻는다.",
      "trapAnalysis": "이 유형에서 오답을 유도하는 대표 패턴은 다음과 같다.\n\n(1) '잔액 처리' 종착지 바꿔치기 — 충당 후 남은 금액은 '제공자에게 반환(돌려줌)'이 원칙이고, 돌려줄 수 없을 때는 '공탁'(관세법 제25조제2항, '공탁할 수 있다')이 정답인데, 선지는 그럴듯하게 '즉시 국고에 귀속'으로 끝맺어 함정을 만든다(2021 Q12-④). '국고 귀속'은 무주물·몰수물 등 다른 제도의 용어를 끌어와 혼동시키는 전형적 오답이다.\n\n(2) 담보 '종류'에 비슷하지만 빠진 항목 끼워 넣기 — '보험에 가입된 등록된 차량(자동차)'처럼, 보험에 든 등기·등록 건물·선박·항공기·건설기계는 인정되나 '자동차'는 열거(제24조제1항)에 없다는 점을 노린다(2019 Q22-나, answer ②). '국채·지방채는 되는데 회사채는?', '토지는 되는데 건물은 무조건 되는가(→보험가입+등기·등록 요건 필요)' 식으로도 변형된다.\n\n(3) 충당 절차 주체·방법 비틀기 — 납세보증보험증권·납세보증서는 '보증인에게 즉시 통보'(제25조 위임 시행규칙)가 옳은 절차인데, 이를 '담보물 직접 매각' 등으로 바꾸거나 통보 대상을 바꿔 오답을 만든다(2021 Q12-⑤는 옳은 선지로 출제).\n\n(4) 기간 숫자 함정 — 담보 미제공 시 납부고지 기준이 '담보액 확정일부터 10일 이내'(시행령 제10조)인데 '7일/15일'로 바꾸는 식의 숫자 변형.",
      "answerKey": "정답은 ④이다.\n\n④가 틀린 이유: 관세법 제25조제2항에 따라 세관장은 담보를 관세에 충당하고 남은 금액이 있으면 담보를 제공한 자에게 돌려주어야 하며, 돌려줄 수 없는 경우에는 이를 '공탁할 수 있다'. 선지는 '즉시 국고에 귀속한다'고 하여 처리 방법을 잘못 기술하였으므로 틀린 설명이다(국고귀속은 무주물·몰수물 등 다른 제도의 종착지).\n\n나머지가 옳은 이유:\n① 천재지변 등으로 납부기한을 연장하는 경우 세관장은 납부할 관세에 상당하는 담보를 제공하게 할 수 있다 — 옳다.\n② 계속하여 담보를 제공해야 하는 사유가 있으면 일정 기간 제공할 담보를 포괄하여 미리 제공할 수 있다(포괄담보, 관세법 제24조제4항) — 옳다.\n③ 담보를 제공하려는 자가 담보액 확정일부터 10일 이내에 담보를 제공하지 아니하면 세관장은 납부고지를 할 수 있다(관세법 시행령 제10조, 법 제39조) — 옳다.\n⑤ 담보물이 납세보증보험증권인 경우 그 관세충당은 보증인에게 담보한 관세에 상당하는 금액을 납부할 것을 즉시 통보하는 방법에 따른다(제25조 위임 시행규칙) — 옳다.\n\n[참고] 2019 Q22(담보의 종류)는 '보험에 가입된 등록된 차량'이 정답(틀린 것, answer ②)으로, 자동차가 담보 종류 열거(제24조)에 없다는 점을 묻는다. 2023 Q14는 담보가 아닌 '수입신고 시기·신고세관'(정답 ④) 문항으로 본 유형과 직접 관련은 적다.",
