      "conceptExplanation": "관세감면은 일정한 정책목적(외교·학술·산업지원·국민편의 등)을 위해 수입물품에 부과될 관세를 면제하거나 경감해 주는 제도로, 보세사 1과목(수출입통관절차)에서 매년 1~3문항씩 출제되는 빈출 영역이다. 크게 ① 조건 없이 즉시 면제되는 「무조건 감면」과 ② 일정 용도·기간 등 조건을 붙여 사후관리를 전제로 하는 「조건부(사후관리) 감면」으로 나뉜다.\n\n[주요 감면 조항]\n- 제89조(세율불균형물품의 감면): 항공기·반도체 제조용 부분품·원재료 등 세율불균형 시정 목적. 중소기업뿐 아니라 항공기 제조·수리업 등 일정 요건을 갖춘 자도 적용 가능(중소기업 전용 아님).\n- 제90조(학술연구용품의 감면): 학교·공공의료기관·공공직업훈련원·박물관·과학기술연구기관 등이 학술연구·교육·훈련·실험용으로 수입하는 표본·참고품·시약·실험용 기계기구 등.\n- 제91조(종교용품·자선용품·장애인용품 등의 면세): 종교의식용품, 자선·구호용품, 시각장애인용 특수제작 물품 등. → 용도 조건이 있어 사후관리 대상.\n- 제93조(외국 원수 등에 대한 면세): 우리나라를 방문하는 외국 원수와 그 가족·수행원의 물품(소액물품 면세인 제94조와 혼동 금지).\n- 제94조(소액물품 등의 면세): 견본품(과세가격 미화 250달러 이하), 자가사용 물품(물품가격 미화 150달러 이하), 상품목록·가격표·교역안내서, 수여된 훈장·기장 등.\n- 제96조(여행자 휴대품·이사물품 등의 감면): 이사물품은 우리나라 국민(재외영주권자 제외)으로서 외국에 1년 이상 거주한 사람이 반입하는 물품으로, 입국 전 3개월 이상 사용하고 입국 후 계속 사용 인정되는 가정용품 등.\n- 제97조(재수출면세): 수입 후 일정 기간(원칙 1년, 부득이한 경우 연장) 내에 다시 수출되는 물품(일시수입). 기간 내 미수출 시 면제관세를 즉시 징수하고 가산세 부과 가능.\n- 제98조(재수출 감면): 장기간(2년 초과) 사용하는 기계·시설 등을 임대차·도급계약 등에 따라 일시 수입하는 경우 사용기간별로 차등 경감.\n- 제99조(재수입면세): 우리나라에서 수출된 물품이 가공·수리되지 않고 수출신고 수리일부터 2년 내에 다시 수입되는 경우(원상태 재수입). 해외 설치·조립·하역용 수출장비로서 2년 내 재수입되는 물품 포함. 단, 보세가공·관세환급을 받은 물품 등은 제외.\n- 제101조(해외임가공물품 등의 감면): 원재료·부분품을 수출하여 해외에서 가공·조립한 후 수입하는 물품의 가공·조립 부가가치분 감면.\n\n[감면 신청 시기] 원칙적으로 해당 물품의 수입신고 수리 전에 감면신청서를 세관장에게 제출(다만 부과고지 물품 등은 예외 인정 → \"예외 없이\"라는 표현은 함정).\n\n[사후관리(제102조)] 조건부 감면(제89조 일부·제90조·제91조·제93조 일부·제95조·제98조 등)은 감면물품을 정해진 용도로 사용해야 하며, 용도 외 사용·양도·임대 시 감면관세를 징수한다. 사후관리기간은 동일물품에 여러 기간이 적용되면 그 중 「가장 짧은 기간」으로 한다(\"가장 긴 기간\"은 오답 함정). 반면 정부물품(제92조)·소액물품(제94조)·여행자휴대품·이사물품(제96조)·해외임가공물품(제101조) 등은 사후관리 없이 즉시 감면된다.",
      "trapAnalysis": "관세감면 유형의 오답은 ① 숫자·기간 바꿔치기, ② \"예외 없이/모두/만\" 같은 절대표현, ③ 사후관리 기간의 장단 뒤집기, ④ 면제 조항을 서로 섞기(제93조 외국원수 ↔ 제94조 소액물품), ⑤ 징수 여부를 정반대로 서술하는 방식으로 유도된다.\n- 선지①: \"예외 없이\"라는 절대표현이 함정. 감면신청은 원칙적으로 수입신고 수리 전이지만 부과고지 물품 등 예외가 있으므로 \"예외 없이\"는 틀린다.\n- 선지②: 사후관리기간이 여럿이면 \"가장 짧은 기간\"으로 하는데 \"가장 긴 기간\"으로 뒤집어 오답을 유도(2023 Q8 대표 함정).\n- 선지③: \"중소기업만\"이라는 한정이 함정. 제89조 세율불균형물품 감면은 항공기 제조·수리업 등도 적용받으므로 중소기업 전용이 아니다.\n- 선지⑤: 용도 외 사용·양도·임대 시 감면관세를 \"징수한다\"가 정답인데 \"징수하지 않는다\"로 뒤집은 전형적 역서술 함정.\n- 소액물품 문항(2021 Q13)에서는 외국 원수·가족·수행원 물품(제93조)을 소액물품 면세(제94조)에 끼워 넣어 조항을 혼동시키는 패턴이 출제된다.",
      "answerKey": "정답은 ④. 관세법 제99조(재수입면세)는 수출물품을 해외에서 설치·조립 또는 하역하기 위하여 사용하는 장비로서 우리나라에서 수출신고 수리일부터 2년 내에 다시 수입되는 물품의 관세를 면제할 수 있도록 규정한다 — 조문에 정확히 부합한다.\n- ①(오답): 감면신청은 원칙적으로 수입신고 수리 전에 하지만 부과고지 물품 등 예외가 있어 \"예외 없이\"는 틀리다.\n- ②(오답): 동일물품에 사후관리기간이 다르게 적용되면 그 중 \"가장 짧은 기간\"으로 정한다. \"가장 긴 기간\"은 틀리다.\n- ③(오답): 제89조 세율불균형물품 감면은 중소기업뿐 아니라 항공기 제조업 등 일정 요건을 갖춘 자도 적용받으므로 \"중소기업만\"은 틀리다.\n- ⑤(오답): 세관장 승인을 얻어 감면물품을 용도 외 사용·양도·임대하는 경우에는 감면된 관세를 \"징수한다\". \"징수하지 않는다\"는 틀리다.",
