      "conceptExplanation": "관세법 제12조(장부 등의 보관)와 동법 시행령 제3조는 수출입 신고 관련 서류·자료를 「신고 수리일」을 기산점으로 하여 자료의 성격(중요도·과세 관련성)에 따라 5년·3년·2년의 세 단계로 차등 보관하도록 규정한다. 이는 사후 세액 심사·관세조사·과세가격 검증의 실효성을 확보하기 위한 장치다.\n\n【5년 보관】 수입 관련(과세가 발생하는 쪽) 핵심 서류 — ① 수입신고필증 ② 수입거래 관련 계약서(수입거래계약서) ③ 지식재산권의 거래에 관련된 계약서 ④ 수입물품 과세가격 결정에 관한 자료(가격결정자료). 즉 「수입+과세·권리」 계열은 가장 길게 5년.\n\n【3년 보관】 수출·반송 관련(과세가 원칙적으로 없는 쪽) 서류 — ① 수출신고필증 ② 반송신고필증 ③ 수출물품·반송물품 가격결정에 관한 자료 ④ 수출거래·반송거래 관련 계약서. 즉 「수출/반송」 계열은 중간 단계인 3년.\n\n【2년 보관】 화물의 물리적 이동·보관 관리 자료 — ① 보세화물반출입에 관한 자료(보세화물반출입신고필증) ② 적재화물목록(적하목록)에 관한 자료 ③ 보세운송에 관한 자료(보세운송신고필증). 즉 「화물관리(반출입·적하목록·보세운송)」 계열은 가장 짧은 2년.\n\n핵심 암기 구도는 「수입·과세·권리=5년 > 수출·반송=3년 > 화물관리=2년」이며, 보관기간의 기산점은 모두 「해당 신고 수리일」이다. 출제는 (a) 가장 긴/짧은 서류를 묻는 긍정형(2025), (b) 나열된 보관기간 중 틀린 것을 찾는 부정형(2020), (c) 보관기간 서술 중 맞는 것을 찾는 긍정형(2022) 등 다양한 형태로 변주된다.",
      "trapAnalysis": "이 유형의 대표 함정은 「보관기간 한 단계 밀어내기」다. 출제자는 2년짜리 화물관리 자료(보세화물반출입·적하목록·보세운송)를 한 단계 위인 3년으로, 또는 3년짜리 수출신고필증을 5년 또는 2년으로 슬쩍 바꿔 오답을 만든다.\n\n구체적 함정 패턴:\n1) 「보세화물반출입 자료=3년」 식으로 2년 자료를 3년처럼 보이게 함(2020 Q2 정답 선지의 핵심 트릭). 보세화물반출입·적하목록·보세운송은 전부 2년임을 외우면 한 방에 걸러진다.\n2) 「수입물품 가격결정 자료=3년」처럼 수입(5년) 계열을 수출(3년) 계열로 끌어내림(2022 Q9 ②번 오답).\n3) 「수출신고필증=2년」처럼 3년을 2년으로(2022 Q9 ⑤번 오답).\n4) 긍정형(2025 Q4)에서는 「가장 긴/짧은」을 물어 수입신고필증(5년)과 수출·반송신고필증(3년), 화물관리 자료(2년)의 상대 순위를 정확히 알아야만 풀 수 있게 함.\n5) 기산점 함정: 「신고일」이 아니라 「신고 수리일」부터 기산한다는 점을 바꿔 출제할 수 있다.",
      "answerKey": "정답은 ③(보세화물 반출입에 관한 자료: 3년)이다. 보세화물반출입에 관한 자료(보세화물반출입신고필증)는 관세법 시행령 제3조상 보관기간이 「2년」이므로, 이를 「3년」이라 적은 ③이 틀린 설명(부정형 발문의 정답)이다.\n\n나머지 선지가 옳은 이유:\n① 수입신고필증=5년 — 수입·과세 계열로 최장 5년이 맞다.\n② 수출신고필증=3년 — 수출/반송 계열로 3년이 맞다.\n④ 수입물품 과세가격 결정 자료=5년 — 수입 과세가격 관련 핵심 자료로 5년이 맞다.\n⑤ 보세운송에 관한 자료=2년 — 화물관리 계열로 2년이 맞다.\n따라서 보관기간이 규정과 어긋난 것은 ③ 하나뿐이다.",
