      "lawBasis": "관세법 제118조(과세전적부심사 — 과세전통지, 통지 받은 날부터 30일 청구·청구 받은 날부터 30일 결정통지, 제1항 단서 생략사유 6호: 제척기간 3개월 내 만료/확정가격 신고/수입신고 수리 전 세액심사 결과 부족세액 징수/면제·감면관세 추징/관세포탈죄 고발 징수/징수곤란 등), 제119조(불복의 신청 — 통고처분·「감사원법」에 따라 심사청구를 한 처분 등 제외[제1항 단서 제1·2호], 제2차 납세의무자 등 이해관계인의 청구[제9항], 동일 처분에 대한 심사청구·심판청구 중복 제기 금지[제10항]), 제120조(「행정소송법」 등과의 관계), 제121조(심사청구기간 — 처분이 있은 것을 안 날부터 90일, 이의신청 결정통지일부터 90일), 제122조(심사청구절차 — 처분 세관장 경유, 관세청장에게, 세관장은 받은 날부터 7일 내 의견서 첨부 송부), 감사원법 제43조·제44조(감사원 심사청구).",
