      "conceptExplanation": "수입통관은 ①정식 수입신고(첨부서류 일체 제출) ②간이신고(첨부서류 없이 신고서에 신고사항만 기재) ③수입신고 생략(신고 자체를 면제) 의 3단계로 절차가 차등화되며, 이 유형은 그중 「간이신고 대상」과 「신고생략 대상」을 정확히 구별할 수 있는지를 묻는다. 근거는 「수입통관 사무처리에 관한 고시」다.\n\n[간이신고 대상 — 신고서는 제출하되 첨부서류를 생략]\n① 국내거주자가 수취하는 자가사용물품으로서 물품가격이 미화 150달러(한미 FTA 협정 해당물품은 200달러) 이하인 면세대상물품\n② 상업용 견본품(상용견품)으로서 과세가격 미화 250달러 이하의 면세대상물품 (2019~2023 기출 모두 '과세가격 250달러 이하'로 일관. ※2025형 빈칸문제의 정답키는 '물품가격·300달러'로 되어 있어 현행 공식기준과 상충 — 출제·정답 오류 소지로 별도 주의)\n③ 설계도 중 수입승인이 면제되는 것\n④ 외국환거래법에 따라 금융기관이 외환업무를 영위하기 위하여 수입하는 지급수단\n\n[신고생략 대상 — 신고서 제출 자체를 면제]\n① 외교행낭으로 반입되는 면세대상물품(외교관계 협약상 검사·신고 면제)\n② 우리나라에 내방하는 외국 원수와 그 가족·수행원에 속하는 면세대상물품\n③ 장례를 위한 유해로서 관세가 면제되는 물품\n④ 기록문서·서류로서 관세가 면제되는 물품\n⑤ 재외공관 등에서 외교부(외교통상부)로 발송되는 자료로서 관세가 면제되는 물품\n⑥ 그 밖에 관세가 면제되는 우편물 중 소액 물품 등\n\n[핵심 구별 포인트]\n- 간이신고는 '신고서는 낸다(첨부서류만 생략)'이고, 신고생략은 '신고서조차 안 낸다'는 점에서 단계가 다르다.\n- 외교 관련 물품(외교행낭·외국 원수 수행원·재외공관 발송자료) 및 유해·기록서류는 '신고생략' 영역이며, 간이신고 대상으로 출제되면 오답이다.\n- 우편물은 무조건 간이/생략이 아니라 '소액 기준 이하'일 때만 간이통관 대상이고, 기준(과세가격·물품가격)을 초과하면 정식 수입신고를 해야 한다(2023 Q15의 미화 1,500불 우편물 = 정식신고).\n- 금액 기준 암기가 결정적이다: 자가사용물품 150달러(한미 200달러), 상용견품 250달러 이하.",
      "trapAnalysis": "금액 기준 변형 함정 부분을 다음과 같이 교정: 「상용견품(견본품)의 간이신고 기준은 현행 「수입통관 사무처리에 관한 고시」상 '과세가격 미화 250달러 이하'(운임 포함)이며, 2020·2022·2023 기출 모두 동일하게 '과세가격 250불 이하'로 출제되었다. 다만 2025 Q24 근거파일의 정답키는 '물품가격·300달러'로 되어 있어 현행 공식 기준(과세가격 250달러)과 상충하므로, 이는 출제·정답 오류 가능성이 있는 구간이다. 따라서 '2025 고시 개정으로 견본품 300달러까지 확대'라고 단정하지 말고, 시험상으로는 ⓐ공식 기준=과세가격 250달러 이하를 기본으로 암기하되 ⓑ2025형 빈칸문제의 정답키(물품가격/300달러)는 별도 주의(논란/오류 소지)로 인지할 것.」 나머지(외교행낭=신고생략, 우편물 1,500불=정식신고, 긍정/부정형 전환)는 정확하므로 유지.",
      "answerKey": "발문이 '간이신고 대상물품이 아닌 것'을 고르는 부정형이므로, 간이신고가 아닌 신고생략 대상을 골라야 한다. 정답은 ②'외교행낭으로 반입되는 면세대상물품'이다. 외교행낭은 외교관계 협약에 따라 수입신고 자체를 면제(신고생략)하는 물품이지, 신고서를 제출하는 간이신고 대상이 아니다.\n\n나머지는 모두 「수입통관 사무처리에 관한 고시」상 간이신고(첨부서류 없이 신고서 기재) 대상에 해당하여 오답이다: ① 자가사용물품 미화 150달러 이하 면세물품(간이신고 대상), ③ 상용견품 미화 250불 이하 면세물품(간이신고 대상), ④ 수입승인이 면제되는 설계도(간이신고 대상), ⑤ 외국환거래법상 금융기관이 외환업무를 위해 수입하는 지급수단(간이신고 대상).",
