      "lawBasis": "관세법 제253조(수입신고전의 물품 반출): 즉시반출신고·담보 제공, 즉시반출신고일부터 10일 이내 수입신고, 미신고 시 관세 즉시 징수 및 관세 100분의 20 가산세·지정 취소. 관세법 제252조(수입신고수리전 반출): 통관에 곤란한 사유가 없는 물품에 대한 세관장 승인 및 담보 제공. 수입통관 사무처리 고시(수리전 반출 승인 대상 사유). 관세법 시행령 제236조(원산지증명서 제출).",
