      "conceptExplanation": "이 유형은 관세법 제246조(물품의 검사) → 제246조의2(물품 등의 검사에 대한 손실보상) → 제246조의3(수출입물품의 안전성 검사)으로 이어지는 '검사 3종 세트'를 묶어 묻는다.\n\n[1] 물품검사(제246조): ①세관공무원은 수출·수입 또는 반송하려는 물품을 검사할 수 있다. ②관세청장은 검사의 효율을 위해 검사대상·검사범위·검사방법 등에 관한 기준을 정할 수 있다. ③화주는 수입신고를 하려는 물품에 대하여 '수입신고 전에' 관세청장이 정하는 바에 따라 확인할 수 있다(신고 전 물품확인). ④세관장은 효율적 검사를 위해 부득이하다고 인정될 때에는 관세청장이 정하는 바에 따라 해당 물품을 보세구역에 반입하게 한 후 검사할 수 있다. ⑤검사 참여 신청은 '화주 또는 신고인'이 할 수 있고 세관장이 이를 허용할 수 있다(화주만으로 한정 X). 검사방법으로는 발췌검사·전량검사·협업검사·안전성분석검사·파괴검사 등이 있다('원격지화상검사' 같은 명칭은 규정상 없음).\n\n[2] 손실보상(제246조의2): 관세청장 또는 세관장은 세관공무원의 '적법한' 물품검사로 인하여 물품·운송수단에 손실이 발생한 경우 그 손실을 입은 자에게 보상하여야 한다('보상할 필요가 없다'는 표현은 함정). 보상기준은 ▲수리할 수 있는 경우: 수리비 상당액(별도 상한 금액 규정 없음 — '200만원 초과 불가' 같은 한도는 함정), ▲수리할 수 없는 경우: 구매가격 및 손실을 입은 자가 청구하는 금액을 고려하여 관세청장이 합리적인 범위에서 인정하는 금액. 검사 대상 물품을 포장한 용기도 손상 시 보상대상이 될 수 있다. 손실보상의 지급절차·방법 등 필요한 사항은 '관세청장'이 정한다(세관장 X).\n\n[3] 안전성 검사(제246조의3): 세관장은 다른 법령에서 정한 물품의 성분·품질 등에 대한 안전성 검사를 '중앙행정기관의 장과 협력하여' 실시하여야 한다. 관세청장은 안전성 검사를 위하여 '협업검사센터'를 주요 공항·항만에 설치할 수 있고, 검사 결과 불법·불량·유해 물품으로 확인된 물품의 정보는 '관세청 인터넷 홈페이지'를 통하여 공개할 수 있다. 또한 안전성 검사가 필요한 경우는 통관보류 사유(제237조)에도 해당한다.\n\n요컨대 이 유형은 (1) 검사 주체·대상·참여자, (2) 손실보상의 요건·산정기준·소관기관, (3) 안전성 검사의 협력기관·시설·공개매체 세 축을 정확한 숫자·명칭·주체로 변별하는 것이 핵심이다.",
      "trapAnalysis": "이 유형의 오답 유도는 '정반대 서술'과 '숫자·주체 바꿔치기'가 핵심이다. (1) 손실보상 의무를 정반대로 뒤집기: \"보상할 필요가 없다\"(2023 Q20 ④) — 실제로는 적법한 검사로 손실이 나면 '보상하여야 한다'(제246조의2). (2) 산정기준에 가짜 상한 끼워넣기: \"수리비 상당액을 지급하되 200만원을 초과할 수 없다\"(2024 Q6 ⑤) — 상한 금액 규정 자체가 없음. (3) 소관기관 바꿔치기: 손실보상 지급절차를 '세관장이 정한다'로 둔갑(2024 Q6 ④) — 실제는 '관세청장'. (4) 검사 참여자 축소: 참여 신청을 '화주에 한하여' 허용(2020 Q6 ⑤) — 실제는 '화주 또는 신고인'. (5) 안전성 검사 협력기관·시설명·공개매체를 비슷한 명칭과 바꿔치기: '수출입기업지원센터↔협업검사센터', '화물관리인↔중앙행정기관의 장', '관보·일간신문↔관세청 인터넷 홈페이지'(2024 Q19). (6) 존재하지 않는 검사방법명 끼워넣기: '원격지화상검사'(2024 Q25). (7) '수리할 수 없는 경우'의 보상을 단순히 '물품의 구입가격'으로 단정(2024 Q6 ②) — 검사 대상 물품은 1차적으로 과세가격(법 제30~35조), 산정 불가 시 구매가격 및 청구금액을 고려하여 관세청장이 합리적 범위에서 인정하는 금액(운송수단·용기는 구매가격+청구금액 기준). [추가 함정] 조문 위치 바꿔치기: 대표문항 선지 ⑤ '보세구역 반입 후 검사'는 제246조가 아니라 제247조(검사 장소) 제2항 소관이므로, 조문 근거를 묻는 변형 출제 시 '제246조 제O항'으로 유도하면 오답이다.",
      "answerKey": "정답은 ④이다. 관세법 제246조의2(물품 등의 검사에 대한 손실보상)는 관세청장 또는 세관장이 세관공무원의 '적법한' 물품검사로 물품에 손실이 발생한 경우 그 손실을 입은 자에게 보상'하여야 한다'고 규정한다. ④는 \"보상할 필요가 없다\"고 하여 손실보상 의무를 정반대로 서술했으므로 틀린 설명(정답)이다.\n\n나머지 선지가 옳은 이유: ① 세관공무원이 수출·수입·반송 물품을 검사할 수 있다는 것은 제246조 제1항에 부합한다. ② 관세청장이 검사대상·범위·방법 기준을 정할 수 있다는 것은 제246조 제2항에 부합한다. ③ 화주가 수입신고 전에 관세청장이 정하는 바에 따라 물품을 확인할 수 있다는 것은 제246조 제3항(신고 전 물품확인)에 부합한다. ⑤ 세관장이 부득이한 경우 물품을 보세구역에 반입하게 한 후 검사할 수 있다는 것은 제247조(검사 장소) 제2항에 부합한다(제246조가 아님에 유의).",
      "cautions": [
        "손실보상의 전제는 '적법한' 검사다. 위법한 검사로 인한 손해는 손실보상(제246조의2)이 아니라 국가배상의 영역이다.",
        "손실보상 지급절차·방법 등을 정하는 주체는 '관세청장'이지 세관장이 아니다(2024 Q6 ④ 함정).",
        "검사 참여 신청은 '화주 또는 신고인'이 가능하다. '화주에 한하여'로 좁히면 오답(2020 Q6 ⑤).",
        "수리 가능한 물품의 보상은 수리비 상당액이며, 별도의 상한 금액(예: 200만원) 규정은 없다(2024 Q6 ⑤ 함정).",
        "안전성 검사의 협력 상대는 '중앙행정기관의 장', 설치 시설은 '협업검사센터', 정보공개 매체는 '관세청 인터넷 홈페이지' — 세 가지를 한 묶음으로 암기(2024 Q19).",
        "검사방법 명칭에서 '발췌검사·전량검사·협업검사·안전성분석검사·파괴검사'는 실재하나 '원격지화상검사'는 존재하지 않는 함정 명칭이다(2024 Q25).",
        "안전성 검사가 필요한 경우는 통관보류 사유(제237조)이기도 하다 — 검사와 통관보류를 연결해 묻는 변형 출제 주의."
      ],
