      "conceptExplanation": "이 유형은 「수입통관 사무처리에 관한 고시」를 중심으로 ① 수입신고의 처리(서류제출대상 선별·신고서 처리기간 기산), ② 제출서류의 전자화(스캔 전자이미지·무역서류 전자제출) 원칙과 그 예외(종이서류 제출), ③ 통관 시 제출하는 무역서류(부속서류)의 범위, ④ 수입물품에 부착하는 통관표지를 묻는다.\n\n(1) 서류제출 방식 — 전자제출 원칙: 서류제출대상으로 선별된 수입신고건은 송품장(인보이스)·가격신고서·선하증권(B/L) 부본·항공화물운송장(AWB) 부본·원산지증명서 등 첨부서류를 스캔하여 전자이미지화하거나 무역서류 전자제출(EDI)로 통관시스템에 전송하는 것이 원칙이다. 다만 원본 확인이 필수인 일부 서류는 예외적으로 종이서류(원본)로 제출해야 한다. 대표적으로 킴벌리프로세스증명서(분쟁지역 다이아몬드 원석 원산지 통제용 국제협약 증명서)와 A.T.A Carnet(일시수입통관증서)에 의한 일시수입물품 증서가 종이 원본 제출 대상이다.\n\n(2) 무역서류(부속서류)의 범위: 고시상 수입신고 시 제출하는 부속서류는 송품장(invoice), 선하증권(B/L)·항공화물운송장(AWB), 포장명세서(packing list), (필요 시) 원산지증명서 등이다. 구매계약서는 실무 참고자료일 뿐 고시가 정한 법정 부속서류에 해당하지 않는다.\n\n(3) 간이신고·서류생략: 미화 150달러 이하 자가사용 면세물품, 미화 250달러 이하 면세 상용견품, 수입승인 면제 설계도, 외국환거래법상 금융기관이 수입하는 지급수단 등은 첨부서류 없이 신고서에 기재하는 간이신고 대상이다. 반면 외교행낭 반입 면세물품은 수입신고 자체를 생략하므로 간이신고 대상이 아니다.\n\n(4) 신고서 처리기간 기산일: 보세구역 장치 후 신고물품·선상 적재상태 검사물품은 「수입신고일」, 보세구역 도착전신고 검사생략물품은 「보세구역 도착일」, 검사대상 선별물품은 「검사장소 반입일」을 기산일로 한다. 특히 입항전신고를 한 물품(검사생략)의 처리기간은 신고일이 아니라 실제 「입항일」부터 기산하는 점이 함정이다.\n\n(5) 통관표지: 수입물품 통제를 위해 부착하며, 재수출(재수입) 예정 물품 등 국내 유통되지 않는 물품은 표지 부착 실익이 없어 첨부를 생략할 수 있다. 표지의 첨부는 화주·수입자 또는 보세구역 운영인이 할 수 있으나 보관·관리 주체는 화주·수입자이며, 세관장의 비용·책임으로 부착하는 것이 아니다.",
      "trapAnalysis": "① 전자제출이 '원칙'이라는 점을 부각해 거의 모든 첨부서류가 전자화 가능하다는 사실을 깔아둔 뒤, 그 예외(종이 원본)를 정확히 가려낼 수 있는지를 시험한다. 송품장·가격신고서·B/L 부본·원산지증명서를 한꺼번에 보기로 깔아 '익숙한 일반서류'에 손이 가게 유도한다(정답은 생소한 킴벌리프로세스증명서). ② 종이 원본 제출 대상으로는 킴벌리프로세스증명서 외에 A.T.A Carnet 일시수입증서도 출제되는데(2021 Q24), 'A.T.A Carnet은 전자적 방식으로 제출할 수 있다'처럼 정반대로 서술해 틀린 선지를 만든다. ③ 부속서류 범위 문제(2025 Q7)에서는 송품장·B/L·포장명세서·원산지증명서 사이에 '구매계약서'를 끼워 넣어, 실무상 흔히 쓰이는 서류이므로 법정 부속서류로 착각하게 만든다. ④ 처리기간 기산일 문제(2025 Q2)에서는 '입항전신고 검사생략물품'의 기산일을 '수입신고일'로 적어, 다른 선지들과 동일한 패턴(수입신고일)에 묻어 자연스럽게 보이게 만든다(정답은 '입항일'). ⑤ 통관표지 문제(2025 Q8)에서는 'B/L단위 첨부'(실제는 물품·컨테이너 단위), '세관장 비용·책임 첨부'(실제는 화주 또는 보세구역 운영인이 첨부), '보세구역 운영인이 보관·관리'(실제 보관·관리 주체는 화주 또는 수입자) 등 주체·단위를 미묘하게 뒤바꿔 정답(재수출/재수입물품 표지 생략)을 흐린다. ※주의: 보세구역 운영인은 '첨부' 주체로는 등장하나 '보관·관리' 주체는 아니므로, 둘을 구분해야 한다.",
      "answerKey": "정답은 ④ 킴벌리프로세스증명서. 킴벌리프로세스증명서는 분쟁지역 다이아몬드 원석의 원산지를 통제하기 위한 국제협약(킴벌리 프로세스) 증명서로, 원본 진위 확인이 필수이므로 스캔 전자이미지가 아닌 종이서류(원본)로 제출해야 한다. 나머지 ① 송품장, ② 가격신고서, ③ 선하증권(B/L) 부본·항공화물운송장(AWB) 부본, ⑤ 원산지증명서는 모두 스캔 전자이미지화하거나 무역서류 전자제출(EDI)로 갈음할 수 있어 종이서류 제출 대상이 아니다.",
