      "lawBasis": "관세법 제241조(수출·수입 또는 반송의 신고), 제246조(물품의 검사), 제248조(신고의 수리), 제250조(신고의 취하 및 각하); 전자신고·전자제출의 근거는 제327조(국가관세종합정보시스템의 구축·운영)(제254조 아님 — 제254조는 '전자상거래물품의 특별통관'). 절차상 세부는 「수입통관 사무처리에 관한 고시」의 서류제출대상 선별·전자이미지 제출·무역서류 전자제출, 간이신고 대상물품, 신고서 처리기간, 통관표지 관련 규정에 따른다(구체 조번호는 고시 개정으로 변동 가능하므로 단정 인용 지양). 킴벌리프로세스증명서·A.T.A Carnet 일시수입증서의 종이 원본 제출은 동 고시상 서류제출 특례에 따른다.",
