      "lawBasis": "관세법 제243조 제4항(신고의 요건 — 밀수출 등 불법행위가 발생할 우려가 높거나 감시단속을 위하여 필요하다고 인정하여 대통령령으로 정하는 물품은 관세청장이 정하는 장소에 반입한 후 제241조 제1항에 따른 수출신고를 하게 할 수 있음)이 위임 근거다. 구체적 대상물품 기준(① 도난우려 등 재산권 보호 필요 물품 ② 고세율 원재료 가공수출 등 부정환급 우려 물품 ③ 국민보건·사회안전·국제무역질서 준수 필요 물품)과 AEO 제외 규정은 관세법 시행령 제248조의2(보세구역 반입 후 수출신고의 대상 등) 제1항·제2항(법 제255조의2 제1항에 따라 공인된 수출입 안전관리 우수업체 수출물품은 제외 가능)에 규정되어 있으며, 구체 품목(컨테이너 적입 수출 중고자동차·플라스틱 웨이스트/스크랩 HS 3915·생활폐기물 HSK 3825.10 등)과 반입장소(관세법 제183조 보세창고, 자유무역지역 입주기업체 중 장치장소부호 부여 받은 곳 등)는 시행령 제248조의2 제3항의 위임에 따라 '수출통관 사무처리에 관한 고시'에서 정한다. 반입장소 관련 조문은 관세법 제183조(보세창고)·제197조(종합보세구역, 오답 함정 장소). 보세구역 반입명령은 별개인 관세법 제238조.",
