      "question": "아래의 설명에 해당하는 관세는?\n\n교역상대국이 우리나라의 수출물품 등에 대하여 관세 또는 무역에 관한 국제협정이나 양자 간의 협정 등에 규정된 우리나라의 권익을 부인하거나 제한하는 행위를 하여 우리나라의 무역이익이 침해되는 경우에는 그 나라로부터 수입되는 물품에 대하여 피해상당액의 범위에서 관세를 부과할 수 있다.",
