      "lawBasis": "관세법 제51조(덤핑방지관세의 부과대상), 제56조(덤핑방지관세에 대한 재심사 등), 제57조(상계관세의 부과대상), 제63조(보복관세의 부과대상), 제68조(농림축산물에 대한 특별긴급관세), 제69조(조정관세의 부과대상), 제71조(할당관세), 제50조(세율 적용의 우선순위). ※제50조 우선순위 정밀화: ①1순위=덤핑방지·상계·보복·긴급·특정국물품긴급·농림축산물 특별긴급관세 및 조정관세 중 제69조제2호 → ②2순위=편익관세, 조정관세 중 제69조제1·3·4호 → ③3순위=할당관세·계절관세(단, 할당관세는 그 세율이 2순위보다 낮은 경우에 한해 우선) → ④4순위=국제협력관세·일반특혜관세 → ⑤5순위=잠정세율 → ⑥6순위=기본세율. (현행 조문 기준, 긴급관세는 제65조·특별긴급관세는 제68조로 구분)",
