        "유통이력 신고의무자는 그 자료를 거래일부터 2년간 보관하여야 한다.",
        "세관공무원은 유통이력 신고의무자의 사업장에 출입하여 영업관계의 장부나 서류를 열람하여 조사할 수 있다."
