      "lawBasis": "관세법 제240조의2(통관 후 유통이력 신고): 제1항 신고의무자(외국물품 수입자 및 국내 거래자, 단 소비자 판매를 주된 영업으로 하는 사업자=소매업자 제외)는 관세청장이 지정하는 물품(사회안전 또는 국민보건을 해칠 우려가 현저한 물품 등)의 유통단계별 거래명세를 관세청장에게 신고. 제2항 유통이력을 장부에 기록(전자적 기록방식을 포함한다)하고 그 자료를 「거래일부터 1년간」 보관. (위반 시 제277조에 따른 500만원 이하 과태료.) 관세법 제240조의3(유통이력 조사): 세관공무원의 사업장 출입·영업관계 장부 서류 열람 조사권, 신분증표 제시·관계인 입회, 정당한 사유 없는 조사 거부·방해·기피 금지. ※ 항목 원문이 보관기간을 '5년', 근거 항을 '제3항'으로 적은 것은 오류이며, 정확히는 '거래일부터 1년'·'제2항'이다.",
