      "conceptExplanation": "관세의 분할납부는 일정 요건을 갖춘 경우 관세를 한 번에 내지 않고 여러 차례에 걸쳐 나누어 낼 수 있게 해 주는 제도로, 관세법 제107조에 근거한다. 크게 두 갈래로 나뉜다. (1) 천재지변·재해 등 일반적 사유에 의한 분할납부(제107조 제1항): 세관장은 천재지변이나 그 밖에 대통령령으로 정하는 사유(전쟁·화재 등 재해, 사업의 현저한 손실, 부도·도산 우려 등)로 관세를 정해진 기한까지 납부할 수 없다고 인정될 때 「1년」을 넘지 아니하는 기간을 정하여 관세를 분할하여 납부하게 할 수 있다. (2) 특정 물품에 대한 분할납부(제107조 제2항): 정부·지방자치단체가 수입하는 물품(기획재정부령으로 정하는 물품), 학교·직업훈련원·비영리법인이 수입하는 물품, 의료기관 등의 의료기기, 기업부설연구소·산업기술연구조합의 시험연구용품, 중소제조업체가 직접 사용하려고 수입하는 시설기계류 등에 대하여 세관장은 「5년」을 넘지 아니하는 기간을 정하여 분할납부를 승인할 수 있다. 이러한 분할납부 승인 물품은 그 용도와 양수인이 제한된다. 즉 (가) 정한 기간 내에 해당 용도 외의 다른 용도로 사용하거나, 다른 용도로 사용하려는 자에게 양도하면 「납부하지 아니한 관세의 전액을 즉시 징수」한다. (나) 같은 용도로 사용하려는 자에게 양도한 때에는 「양수인」이 분할납부 의무를 승계하여 관세를 납부한다(양도인이 아님). 또한 분할납부 승인을 받은 자가 정당한 사유 없이 지정된 기한까지 관세를 납부하지 아니하여 징수할 때에는 세관장은 「15일 이내」의 납부기한을 정하여 납세고지하여야 한다. 요컨대 기간 수치(천재지변 1년 / 정부·지자체 등 특정물품 5년)와 용도외 사용·양도 시 미납 관세 전액 즉시 징수, 동일 용도 양도 시 양수인 납부, 미납 시 15일 이내 납세고지가 이 유형의 핵심 출제 포인트다.",
      "trapAnalysis": "이 유형의 함정은 거의 모두 「숫자(기간) 바꿔치기」와 「납부 주체 뒤바꾸기」다. ① 천재지변 등 사유의 분할납부 기간은 1년(제107조 제1항)인데 선지에서는 흔히 「2년」으로 부풀린다(선지 가). ② 정부·지자체 등 특정물품의 분할납부 승인 기간은 5년(제107조 제2항)인데 「10년」으로 늘려 오답을 만든다(선지 나). 1년과 5년 두 수치를 서로 바꾸거나 다른 값(2년·3년·10년)으로 변형하는 것이 가장 잦은 패턴이다. ③ 「동일 용도」 양도 시 납부 주체는 양수인(제107조 제5항)인데 「양도인」으로 바꿔 함정을 판다(선지 다). 동일 용도면 의무가 양수인에게 승계되며, 양도인으로부터 징수 불능 시 양수인으로부터 징수한다는 보충규정까지 있음을 기억해야 한다. ④ 용도외 사용·양도 시 「미납 관세 전액 즉시 징수」(제107조 제9항 제1호)를 분할·일부 징수로 흐리거나, 즉시징수 사유(미납·파산·해산도 포함)를 누락·왜곡하는 변형이 가능하다. ⑤ 미납 시 납세고지 기한 「15일 이내」를 다른 일수로 바꾸는 변형도 출제될 수 있다 — 단, 이 15일 규정은 본법 제107조가 아니라 「관세법 시행령 제127조(관세의 분할납부고지)」가 근거이므로, 조문 귀속을 묻는 변형 출제 시 '제107조'로 단정하지 말 것. 본 문항은 복수정답형(맞는 것 모두 고르기)으로 옳은 선지 라·마를 모두 잡아야 하며 하나만 고르면 오답이다.",
      "answerKey": "정답은 ④(라)와 ⑤(마)이다. ④는 분할납부 승인 물품을 정한 기간에 해당 용도 외의 다른 용도로 사용하거나 다른 용도 사용자에게 양도한 경우 「납부하지 아니한 관세의 전액을 즉시 징수」한다는 관세법 제107조 제9항 제1호의 내용으로 옳다. ⑤는 분할납부 승인자가 정당한 사유 없이 지정된 기한까지 납부하지 아니하여 징수할 때 세관장이 「15일 이내」의 납부기한을 정하여 납세고지하여야 한다는 내용으로 옳다(다만 이 15일 납세고지의 근거는 본법 제107조가 아니라 관세법 시행령 제127조(관세의 분할납부고지)이며, 본법 제107조 제9항은 미납 시 미납 관세 전액 즉시징수만 규정한다). 반면 ①(가)는 천재지변 등 사유의 분할납부 기간이 「2년」이 아니라 「1년」(제107조 제1항)이므로 틀렸고, ②(나)는 정부·지자체 수입물품 등의 분할납부 승인 기간이 「10년」이 아니라 「5년」(제107조 제2항)이므로 틀렸으며, ③(다)는 동일 용도 양도 시 「양도인」이 아니라 「양수인」이 관세를 납부(제107조 제5항)하므로 틀렸다.",
