      "lawBasis": "「수입통관 사무처리에 관한 고시」 별표(통관지세관이 제한되는 특정물품) — 통관지(통관할 수 있는 세관)의 제한은 관세법 본문이 아니라 관세청 고시 별표에 직접 근거한다. 관세청장의 통관절차 운용 권한(수입신고·검사 등 통관 일반 규정)에 터잡은 고시상 제도이다. 주의: 「관세법 제226조(허가·승인 등의 증명 및 확인)」는 '세관장확인물품(요건확인)' 제도의 근거로서 본 통관지세관 제한과는 별개 개념이므로 근거 조문으로 인용하지 않는다.",
