      "lawBasis": "관세법 제8조(기간 및 기한의 계산: 휴일·근로자의 날·대체공휴일 다음 날 특례[제3항], 국가관세종합전산망 장애 시 복구일 다음 날 특례[제4항], 수입신고수리전 반출승인일을 수입신고 수리일로 간주[제2항]), 제9조(관세의 납부기한 등: 신고납부 수리일·부과고지 받은 날·즉시반출 수입신고일부터 각 15일), 제39조(부과고지), 제40조(징수금액의 최저한), 제252조(수입신고수리전 반출), 관세법 시행령 제1조의5(국가관세종합전산망 장애 및 월별납부 승인·유효기간 2년이 되는 날이 속하는 달의 마지막 날), 제37조(징수금액의 최저한·납부일=수입신고수리일)",
