      "question": "관세감면신청서 제출기한에 대한 내용이다. ( ) 안에 들어갈 내용이 순서대로 맞는 것은?\n① 법 기타 관세에 관한 법률 또는 조약에 따라 관세를 감면받으려는 자는 해당물품의 수입신고수리전에 관세감면신청서를 세관장에게 제출하여야 한다.\n② 법 제39조제2항에 따라 관세를 징수하는 경우 해당 납부고지를 받은 날부터 ( )에 감면신청서를 제출할 수 있다.\n③ 수입신고수리전까지 감면신청서를 제출하지 못한 경우 해당 수입신고수리일부터 ( )에 감면신청이 가능하다. (해당 물품이 보세구역에서 반출되지 아니한 경우로 한정한다)",
