      "conceptExplanation": "관세 납세신고는 「신고납부」가 원칙이며, 세액심사는 통상 수입신고수리 후에 한다(사후세액심사 원칙). 그러나 일정 위험·관리 필요 물품은 예외적으로 「수입신고수리 전」에 세액을 심사한다(수리전 세액심사). 「수입통관 사무처리에 관한 고시」(관세법 제38조 및 관련 고시·시행규칙)는 수리전 세액심사 대상물품을 다음과 같이 열거한다. ① 법률 또는 조약에 의하여 관세 또는 내국세를 감면받고자 하는 물품, ② 관세법 제107조에 따라 관세를 분할납부하고자 하는 물품, ③ 관세를 체납하고 있는 자가 신고하는 물품(다만 체납액이 10만원 미만이거나 체납기간이 7일 이내에 수입신고하는 경우는 제외), ④ 납세자의 성실성 등을 참작하여 관세청장이 정하는 기준에 해당하는 불성실신고인이 신고하는 물품, ⑤ 물품의 가격변동이 큰 물품 기타 수입신고수리 후에 세액을 심사하는 것이 적합하지 아니하다고 인정하여 관세청장이 정하는 물품. 즉 감면·분할납부처럼 세액 자체가 사후 정정되기 어렵거나(징수확보가 곤란), 체납자·불성실신고인처럼 세액 확보 위험이 큰 경우, 또는 가격변동이 커서 사후 심사가 부적합한 경우에 한해 수리 전에 미리 세액을 확정·심사한다는 것이 핵심이다. 시험에서는 이 5가지 대상을 그대로 제시하되, 그 중 하나의 숫자(특히 ③의 체납액 기준 10만원, 체납기간 7일)나 조문번호를 살짝 바꿔 「틀린 것」을 고르게 하는 부정형 발문이 전형적이다.",
      "trapAnalysis": "부정형 발문(\"틀린 것은\")에서 핵심 함정은 ③ 체납자 신고물품의 「제외 기준 금액」을 바꿔치기한 것이다. 정답 선지 ③은 제외 기준을 \"체납액 15만원 미만\"이라 했으나, 관세법 시행규칙 제8조 제1항 제3호의 실제 기준은 \"체납액이 10만원 미만이거나 체납기간이 7일 이내에 수입신고하는 경우\"이다. 체납기간 \"7일 이내\"는 그대로 두고 금액만 10만원→15만원으로 바꿔, 익숙한 문장처럼 보이게 만들어 옳은 설명으로 넘기게 유도한다. 나머지 ①·②·④·⑤는 시행규칙 제8조 원문 그대로의 정확한 대상이므로 옳다. 동반 함정: (1) 부정형 발문이라 \"틀린 것=정답\"임을 놓치고 옳은 대상(①·②·④·⑤)을 정답으로 잘못 고르게 하는 발문혼동, (2) ②의 조문번호(제107조 분할납부)나 ③의 체납기간(7일) 같은 다른 숫자를 의심하게 만들어 정작 바뀐 '금액 기준'을 못 잡게 하는 분산 함정. (근거 정밀성: 5대 대상을 열거하는 본원은 「수입통관 사무처리에 관한 고시」가 아니라 관세법 제38조 제2항의 위임을 받은 시행규칙 제8조임.)",
      "answerKey": "정답은 ③(다)이다. 관세를 체납하고 있는 자가 신고하는 물품은 수리전 세액심사 대상이 맞으나, 그 「제외」 기준은 \"체납액이 10만원 미만이거나 체납기간이 7일 이내에 수입신고하는 경우\"이다. ③은 \"체납액이 15만원 미만\"이라 하여 금액 기준을 틀리게 서술했으므로 틀린 설명(=부정형 발문의 정답)이다. 나머지는 모두 옳다. ①(가) 법률·조약에 의한 관세·내국세 감면 신청 물품, ②(나) 관세법 제107조 분할납부 신청 물품, ④(라) 관세청장이 정하는 기준의 불성실신고인 신고물품, ⑤(마) 가격변동이 큰 물품 등 수리후 세액심사가 적합하지 아니하다고 관세청장이 정하는 물품은 모두 수입신고수리전 세액심사 대상 그대로다.",
