      "conceptExplanation": "국제무역선·국제무역기와 국경출입차량이 국제항·통관역·통관장을 드나들 때, 관세법은 각 행위를 「세관장의 허가」를 받아야 하는 것과 「세관장에게 신고」하면 되는 것으로 엄격히 구분한다. 이 둘은 통제 강도가 다르다. ▶입항(들어오는 행위)은 원칙적으로 「신고(보고) 사항」이다. 국제무역선·국제무역기가 국제항에 입항하면 선장·기장이 입항보고(입항신고)를 하면 되고, 별도의 사전 허가를 받을 필요가 없다(관세법 제135조 입항절차). 즉 입항은 사후·동시 보고 성격이므로 '허가'가 아니다. ▶반면 출항(나가는 행위)은 「세관장의 허가」 대상이다. 국제무역선·국제무역기가 국제항을 출항하려면 선장·기장이 출항허가를 받아야 한다(관세법 제136조 출항절차). 일단 외국으로 나가면 사후통제가 불가능하므로 사전 허가로 묶어 둔다. ▶내국물품의 적재도 「허가」 대상이다. 국제무역선·국제무역기에는 원칙적으로 외국물품만 싣고, 내국물품을 적재하거나 외국물품을 내국운송하려면 세관장의 허가를 받아야 한다(관세법 제140조). 내국물품이 무세·미통관 상태로 외국으로 유출되는 것을 막기 위함이다. ▶국제항이 아닌 지역(항외)에서의 출입·하역도 「허가」 대상이다. 국제무역선·국제무역기가 국제항의 바깥(항외)에서 물품을 하역하거나 환적하려면 세관장의 허가를 받아야 하며, 국제항이 아닌 지역에 출입할 때도 허가를 받아야 한다(관세법 제134조·제142조). ▶국경출입차량의 경우, 통관역·통관장에 도착(들어옴)할 때는 도착보고(신고)이지만, 통관역·통관장을 출발(나감)하려는 경우에는 세관장의 허가를 받아야 한다(관세법 제149조·제150조). 정리하면 '들어오는 행위(입항·도착)=신고/보고', '나가는 행위(출항·출발)와 물품 유출 위험 행위(내국물품 적재·항외 하역·항외 출입)=허가'라는 큰 틀로 외우면 거의 모든 선지를 가를 수 있다.",
      "trapAnalysis": "이 유형의 최대 함정은 ①「입항」과 ②「출항」을 나란히 배치해 둘 다 같은 '허가'로 착각하게 만드는 대구(對句) 구조다. '입항하려는 경우'와 '출항하려는 경우'는 한 글자 차이로 보이지만, 입항은 신고/보고, 출항은 허가로 법적 취급이 정반대다. 발문이 '허가대상으로 틀린 것'이라는 부정형이어서, 무심코 '드나드는 절차는 다 허가'라고 묶어 버리면 입항(①)을 옳은 것으로 잘못 처리하고 다른 선지를 답으로 고르게 된다. 또 다른 함정은 국경출입차량 선지(⑤ '출발')를 국제무역선 입항(①)과 헷갈리게 하는 것이다. 차량은 '도착=보고, 출발=허가'인데, '출발'이라는 단어 때문에 '나가는 것이니 신고 아닌가'라고 오인하기 쉽다. 내국물품 적재(③)·항외 하역(④)은 '물품 유출 위험'이라는 본질을 모르면 신고로 착각하기 쉬운데, 모두 허가 대상이다. 즉 함정은 '허가/신고의 방향성(들어옴 vs 나감)'과 '물품 유출 위험 여부'를 흐려 놓는 데 있다.",
      "answerKey": "정답은 ①이다. 발문이 '세관장의 허가대상으로 틀린 것'을 묻는 부정형이므로, 허가대상이 아닌 것을 골라야 한다. ① 국제무역선·국제무역기의 국제항 '입항'은 관세법 제135조에 따른 입항절차(입항보고·신고) 대상이지 세관장의 허가 대상이 아니므로, '허가대상'이라고 한 설명이 틀려 정답이 된다. 나머지는 모두 실제 허가대상이라 '틀린 것'에 해당하지 않는다. ② 국제항 '출항'은 제136조 출항절차상 세관장의 허가를 받아야 한다. ③ 국제무역선에 내국물품을 적재하는 것은 제140조에 따라 세관장의 허가가 필요하다. ④ 국제항의 바깥(항외)에서 하역·환적하는 것은 항외 하역·출입으로서 세관장의 허가 대상이다. ⑤ 국경출입차량이 통관역·통관장을 '출발'하려는 경우는 제150조에 따라 세관장의 허가를 받아야 한다(반대로 '도착'은 보고 사항).",
