      "conceptExplanation": "세관은 정해진 개청시간(공무원의 근무시간)과 물품취급시간(보세구역 등에서 물품을 취급하는 시간)에 통관·보세운송 절차를 처리하는 것이 원칙이다. 그러나 수출입업체의 신속통관 수요를 위해, 그 시간 외에도 절차를 진행할 수 있도록 한 제도가 '임시개청 및 시간외 물품취급'이다(관세법 제321조). 핵심은 다음 세 가지다. ①사전통보 의무: 개청시간 외에 통관절차 등을 진행하려는 자는 미리 세관장에게 통보서를 제출하여야 하며, 이 사전통보는 '부득이한 경우를 제외하고는 공무원의 근무시간 내'에 하여야 한다. ②통보서 제출 예외와 별도제출: 관세법 제241조에 따라 신고를 하여야 하는 우편물처럼 정식 신고대상 물품을 취급하는 경우에는 통보서를 제출하여야 하며, 이미 제출한 통보서상의 시간 외에 다시 물품을 취급하는 경우에는 통보서를 별도로 제출하여야 한다. ③수수료 부과: 임시개청·시간외 취급에 대하여는 기본수수료와 가산수수료로 구성된 수수료를 징수한다. 기본수수료는 평일과 공휴일이 서로 다르며(공휴일이 더 높음), 수수료 계산 시 '관세청장이 정하는 물품'은 여러 건의 수출입물품을 1건으로 묶어 통관절차를 신청하는 때에는 이를 1건으로 보아 산정한다. 즉 건수 산정의 특례가 적용된다. 이 유형은 사전통보의 시점(근무시간 내 vs 외), 통보서 제출 의무의 유무, 수수료의 평일·공휴일 차등, 건수 산정 특례를 정확히 구분하느냐를 묻는다.",
      "trapAnalysis": "이 유형의 함정은 모두 '정반대 서술' 또는 '예외 누락'으로 정답처럼 보이게 만드는 패턴이다. ①은 사전통보 시점을 '근무시간 내'에서 '근무시간 외'로 뒤집은 함정으로, 시간 외에 통관하려면 통보 자체는 근무시간 내에 미리 해야 한다는 상식을 거꾸로 적었다. ②는 통보서 제출 의무를 '제출할 필요 없다'로 부정한 함정으로, 제241조 신고대상 우편물은 정식 취급물품이라 통보서가 필요하다. ④는 평일·공휴일 차등이라는 핵심 포인트를 '구분없이 동일'로 지워버린 함정이다(기본수수료는 평일과 공휴일이 다름). ⑤는 '통보서상의 시간 외 취급 시 별도 제출 의무'를 '별도 제출 필요 없다'로 뒤집은 함정이다. 정답 ③만이 건수 산정 특례(여러 건을 1건으로 묶어 신청 시 1건으로 본다)를 규정 그대로 기술하고 있어, 수험생이 '예외·차등·의무'를 정확히 외우지 않으면 ①·②·⑤의 그럴듯한 부정 서술에 끌려가기 쉽다.",
      "answerKey": "정답은 ③이다. 임시개청·시간외 물품취급 수수료를 계산할 때, 관세청장이 정하는 물품의 경우 여러 건의 수출입물품을 1건으로 하여 통관절차를 신청하면 이를 1건으로 보아 수수료를 산정한다(건수 산정의 특례). 나머지가 오답인 이유: ①사전통보는 부득이한 경우를 제외하고 공무원의 '근무시간 내'에 하여야 하므로 '근무시간 외에 하여야 한다'는 틀림. ②관세법 제241조에 따라 신고하여야 하는 우편물을 취급하는 경우에는 통보서를 세관에 '제출하여야' 하므로 '제출할 필요가 없다'는 틀림. ④기본수수료는 평일과 공휴일이 '서로 다르므로' '구분없이 동일하다'는 틀림. ⑤이미 제출한 통보서상의 시간 외에 물품을 취급하는 경우에는 통보서를 '별도로 제출하여야' 하므로 '별도로 제출할 필요가 없다'는 틀림.",
