      "conceptExplanation": "특송물품(국제특송업체가 운송하는 탁송품)은 「특송물품 수입통관 사무처리에 관한 고시」에 따라 물품가격(과세가격이 아닌 거래가격)을 기준으로 세 가지 신고구분으로 나뉜다. ①목록통관특송물품: 국내거주자가 수취하는 자가사용물품 또는 면세되는 상용견품 중 물품가격이 미화 150달러 이하(단, 한미 FTA 협정 대상물품은 200달러 이하)인 물품으로, 정식 수입신고 대신 「통관목록」을 세관장에게 제출하는 것만으로 통관이 이루어진다. ②간이신고특송물품: 물품가격이 150달러(한미협정 200달러)를 초과하고 2,000달러 이하인 물품으로, 첨부서류를 생략하고 간이한 수입신고서로 통관한다. ③일반수입신고특송물품: 물품가격이 미화 2,000달러를 초과하는 물품으로, 일반 수입물품과 동일하게 정식 수입신고 절차를 거친다. 핵심 함정은 '제출 주체'와 '제출 서류'의 매칭이다. 목록통관은 「통관목록」을 제출하며 그 제출 주체는 화물을 운송한 「특송업체」이다(관세사·수입화주가 아니다). 반면 일반·간이 수입신고의 신고 주체는 관세사·관세법인·통관취급법인 또는 수입화주이다. 또한 목록통관 배제대상(의약품, 한약재, 식품류 등 통관목록만으로 통관할 수 없는 물품)은 가격이 150달러 이하라도 간이신고 대상으로 전환된다는 점, FTA 원산지증명 면제대상물품에 협정관세를 적용받으려면 구매처(국가)·가격정보가 담긴 구매영수증 등을 세관장에게 제출하여야 한다는 점도 함께 출제된다.",
      "trapAnalysis": "이 유형의 핵심 함정은 두 가지다. 첫째, '제출 주체 바꿔치기'다. 정답 선지(5)는 목록통관 통관목록의 제출 주체를 '관세사·관세법인·통관취급법인이나 수입화주'로 적었는데, 이 문구는 실제 일반·간이 수입신고의 신고 주체를 그대로 가져온 것이다. 목록통관의 통관목록 제출 주체는 화물을 운송한 「특송업체」이므로, 다른 신고구분의 주체 문구를 붙여 혼동을 유발한다. 둘째, '금액 경계선·예외 흔들기'다. 150/200/2,000달러 경계 숫자, 한미 FTA 200달러 특례를 슬쩍 다른 숫자로 바꾸거나, '150달러 이하'와 '150달러 미만', '2,000달러 이하'와 '2,000달러 미만'처럼 경계 포함 여부(이하/초과)를 비트는 식이다. 또 목록통관 배제대상까지 무조건 목록통관 된다고 단정하거나, FTA 협정관세 적용 시 구매영수증 제출 의무를 누락·왜곡하는 패턴도 자주 등장한다.",
      "answerKey": "발문은 '틀린 것'을 고르는 부정형이다. 정답은 5번. 목록통관특송물품의 통관목록 제출 주체는 화물을 운송한 「특송업체」인데, 선지 5는 이를 '관세사·관세법인·통관취급법인이나 수입화주'라 하여 일반·간이 수입신고의 신고 주체로 잘못 기재했으므로 틀리다. 나머지는 모두 옳다: ①자가사용물품·면세 상용견품 중 미화 150달러(한미협정 200달러) 이하 = 목록통관특송물품, ②150달러(한미협정 200달러) 초과~2,000달러 이하 = 간이신고특송물품, ③2,000달러 초과 = 일반수입신고특송물품, ④FTA 원산지증명 면제대상물품에 협정관세를 적용받으려는 자는 구매처(국가)·가격정보가 담긴 구매영수증 등을 세관장에게 제출하여야 한다 — 모두 고시 규정에 부합한다.",
