      "lawBasis": "관세법 제173조(세관검사장) 제3항 — 세관검사장 반입물품의 채취·운반 등 비용은 화주가 부담하되, 국가는 중소기업·중견기업의 컨테이너 화물로서 수출입 관련 법령을 위반하지 않는 경우 예산의 범위에서 검사비용을 지원할 수 있다. 위임체계: 관세법 시행령 제187조의4(지원 대상·요건) → 「수출입화물 검사 비용 지원 사무처리에 관한 고시」(관세청장). 검사의 근거는 관세법 제246조(물품의 검사). 주의: 관세법 제246조의2(물품의 검사에 따른 손실보상)는 검사로 인한 물품 손실을 보상하는 별개 제도로 '검사비용 지원'과 혼동하지 말 것.",
